window.EXAM_STUDIES = window.EXAM_STUDIES || {}; window.EXAM_STUDIES[35] = {"1":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נק׳) הוכיחו את המשפט השני של ויירשטראס (משפט 5.37): פונקציה רציפה בקטע סגור מקבלת בו מינימום ומקסימום. מספיק להוכיח רק את קיום המקסימום.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשפונקציה רציפה חיה על קטע סגור, יש לה גובה עליון והיא חייבת ממש לגעת בו באיזושהי נקודה בקטע.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשפונקציה רציפה חיה על קטע סגור, יש לה גובה עליון והיא חייבת ממש לגעת בו באיזושהי נקודה בקטע.</p>\n<p><strong>תמונה בראש</strong>: נמלה הולכת על חבל רציף בין שתי נקודות קצה סגורות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>.</span></span> יש תקרה נמוכה ביותר <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> שהחבל אינו עובר אותה. נשלח סדרת נמלים שמתקרבות בגובה לתקרה <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> יותר ויותר; כי הקטע סגור וחסום, חלק מהנמלים מתכנסות למקום אחד <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> בתוך הקטע, ומרציפות הפונקציה יוצא שבמקום <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> החבל מגיע ממש לגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x(2-x)\\)</span> עולה ומקבלת ממש את הגובה המרבי <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>.</span> אילו הקטע היה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1)\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span> הייתה מתקרבת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0.9, 0.99, \\dots\\)</span>)</span> אבל לא הייתה מקבלת אותו כי <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> מחוץ לתחום.</p>\n<p><strong>סופרמום <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\)</span>)</span></strong> הוא החסם מלעיל הקטן ביותר של קבוצת מספרים; <strong>מקסימום</strong> הוא סופרמום שנמצא בעצמו בתוך הקבוצה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>התייחסו לקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> כאל קבוצת הערכים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> על הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לחצו על <strong>קבעו <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span></strong> והקטינו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>:</span> בכל שלב יש איבר של <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> מעל <span class=\"math math-inline\" dir=\"ltr\">\\(M-\\varepsilon\\)</span> (הנקודה הירוקה), וזה בדיוק התהליך שבונה את הסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)&gt;M-\\frac1n\\)</span>.</span></p>\n<figure class=\"demo\" id=\"demo-sup\" data-demo=\"sup\"><noscript><p>ההמחשה האינטראקטיבית דורשת JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: למה יש תקרה $M$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: למה יש תקרה <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></p><div class=\"callout-body\"><p>משפט ויירשטראס הראשון (משפט 5.35) מבטיח שהפונקציה חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> ולכן קיים החסם העליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup f([a,b])\\)</span>.</span></p></div></div>"},{"title":"רמז 2: בונים סדרה שעלייה הפונקציה שואפת ל-$M$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: בונים סדרה שעלייה הפונקציה שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span></p><div class=\"callout-body\"><p>לפי אפיון הסופרמום (טענה 3.9), לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n&lt;f(x_n)\\le M\\)</span>.</span></span> מכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></p></div></div>"},{"title":"רמז 3: חילוץ תת-סדרה מתכנסת ב-$[a,b]$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: חילוץ תת-סדרה מתכנסת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span></p><div class=\"callout-body\"><p>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה בין <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> ולכן לפי בולצאנו-ויירשטראס (משפט 3.32) יש תת-סדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\to c\\)</span>.</span> הראו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>,</span> והשוו את הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_{n_k})\\)</span> לפי היינה (טענה 5.4) ולפי תת-סדרה (משפט 3.25).</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ממשפט ויירשטראס הראשון קבוצת הערכים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה ולכן יש לה חסם עליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> מאפיון הסופרמום נבנה סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> בקטע כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></span> מבולצאנו-ויירשטראס נוציא תת-סדרה המתכנסת לנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>,</span> ומרציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: קיום החסם העליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> ולכן לפי המשפט הראשון של ויירשטראס (משפט 5.35) היא חסומה בו. קבוצת התמונה <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{f(x):x\\in[a,b]\\}\\)</span> אינה ריקה (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\in A\\)</span>)</span> וחסומה מלעיל. לפי אקסיומת השלמות (משפט 3.6), קיים לה חסם עליון סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span>.</span></p>\n<p><strong>שלב 2: בניית סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span></span> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\)</span> אינו חסם מלעיל של <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> לפי טענה 3.9, ולכן קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> שעבורה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M-\\frac1n&lt;f(x_n)\\le M.\\]</div>\n<p><em>למה?</em> אנחנו בונים סדרה של נקודות בקטע שהערכים שלהן מתקרבים בהכרח לתקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> כדי שבהמשך נוכל &quot;להעביר&quot; את התקרה הזאת לנקודת גבול אחת.</p>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\to M\\)</span></span> והסדרה הקבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\to M\\)</span>,</span> לפי משפט הסנדוויץ׳ (משפט 2.32) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}f(x_n)=M\\)</span>.</span></p>\n<p><strong>שלב 3: בחירת תת-סדרה מתכנסת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה. לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת תת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span>,</span> וגבול של סדרות שומר על אי-שוויון חלש (משפט 2.31), נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>\n<p><strong>שלב 4: הוכחת <span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span> וסיום.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> ובפרט בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span> לפי אפיון היינה של רציפות (טענה 5.4), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}f(x_{n_k})=f(c)\\)</span>.</span></p>\n<p>מאידך, <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span> היא תת-סדרה של הסדרה המתכנסת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((f(x_n))\\)</span>,</span> ולכן לפי משפט 3.25 גבולה הוא גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> לפי יחידות הגבול של סדרה (משפט 2.12), <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span></p>\n<p><em>למה?</em> שני הגבולות שייכים לאותה תת-סדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span>:</span> אחד נובע מרציפות הפונקציה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>,</span></span> והשני מכך שזו תת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\le M=f(c)\\)</span>,</span> ולפי הגדרה 5.36 הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> היא המקסימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: קיום החסם העליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> ולכן לפי המשפט הראשון של ויירשטראס (משפט 5.35) היא חסומה בו. קבוצת התמונה <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{f(x):x\\in[a,b]\\}\\)</span> אינה ריקה (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\in A\\)</span>)</span> וחסומה מלעיל. לפי אקסיומת השלמות (משפט 3.6), קיים לה חסם עליון סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span>.</span></p>","<p><strong>שלב 2: בניית סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span></span> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\)</span> אינו חסם מלעיל של <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> לפי טענה 3.9, ולכן קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> שעבורה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M-\\frac1n&lt;f(x_n)\\le M.\\]</div>\n<p><em>למה?</em> אנחנו בונים סדרה של נקודות בקטע שהערכים שלהן מתקרבים בהכרח לתקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> כדי שבהמשך נוכל &quot;להעביר&quot; את התקרה הזאת לנקודת גבול אחת.</p>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\to M\\)</span></span> והסדרה הקבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\to M\\)</span>,</span> לפי משפט הסנדוויץ׳ (משפט 2.32) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}f(x_n)=M\\)</span>.</span></p>","<p><strong>שלב 3: בחירת תת-סדרה מתכנסת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה. לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת תת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span>,</span> וגבול של סדרות שומר על אי-שוויון חלש (משפט 2.31), נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>","<p><strong>שלב 4: הוכחת <span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span> וסיום.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> ובפרט בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span> לפי אפיון היינה של רציפות (טענה 5.4), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}f(x_{n_k})=f(c)\\)</span>.</span></p>\n<p>מאידך, <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span> היא תת-סדרה של הסדרה המתכנסת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((f(x_n))\\)</span>,</span> ולכן לפי משפט 3.25 גבולה הוא גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> לפי יחידות הגבול של סדרה (משפט 2.12), <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span></p>\n<p><em>למה?</em> שני הגבולות שייכים לאותה תת-סדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span>:</span> אחד נובע מרציפות הפונקציה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>,</span></span> והשני מכך שזו תת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\le M=f(c)\\)</span>,</span> ולפי הגדרה 5.36 הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> היא המקסימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להפעיל את הרציפות ישירות על <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> בלי לעבור דרך משפט בולצאנו-ויירשטראס לתת-סדרה מתכנסת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span>.</span></li><li>לשכוח להסביר מדוע <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span> בעזרת שמירת סדר בגבול (משפט 2.31).</li></ul></div></div>"}],"similar":"","mc":null},"2":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> (10 נק׳) הוכיחו את משפט 2.22: מכפלה של סדרה אפסה וסדרה חסומה היא סדרה אפסה.</p>\n<p><strong>ב.</strong> (15 נק׳) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> וגזירה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> הוכיחו או הפריכו את הטענות הבאות:</p>\n<p>(1) אם קיים קבוע <span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\ge c\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=\\infty\\)</span>.</span></p>\n<p>(2) אם לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=\\infty\\)</span>.</span></p>\n<p>(הסעיפים אינם שווים משקל)</p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">גודל שהולך ונמחץ לאפס מנצח גודל אחר שלא בורח לאינסוף — המכפלה שלהם נמחצת לאפס.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: גודל שהולך ונמחץ לאפס מנצח גודל אחר שלא בורח לאינסוף — המכפלה שלהם נמחצת לאפס.</p>\n<p><strong>תמונה בראש</strong>: נניח שיש לכם כדור שקופץ הלוך ושוב בתוך חדר שגובהו לכל היותר <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> מטרים (הסדרה החסומה), אבל אתם מכווצים את הכדור ואת התזוזה שלו בקנה מידה שהולך וקטן לאפס (הסדרה האפסה). אפילו אם הכדור יקפוץ הכי גבוה שמותר לו בחדר <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>),</span> אחרי כיווץ מספיק חזק (שמוקטן <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{M}\\)</span>)</span></span> הוא יהיה קרוב לאפס עד כדי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: אם <span class=\"math math-inline\" dir=\"ltr\">\\(|c_n|&lt;10\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> (חסומה על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\to 0\\)</span>,</span></span> ואנחנו רוצים שהמכפלה <span class=\"math math-inline\" dir=\"ltr\">\\(|b_n c_n|\\)</span> תהיה קטנה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=0.1\\)</span>,</span></span> נבקש <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(|b_n|\\)</span></span> להיות קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0.1}{10}=0.01\\)</span>.</span></span> מאותו רגע המכפלה קטנה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.01\\cdot 10=0.1\\)</span>.</span></span></p>\n<p><strong>סדרה אפסה</strong> היא סדרה שגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span> <strong>סדרה חסומה</strong> היא סדרה שיש קבוע חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|c_n|&lt;M\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגורם הירוק <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(2x)\\)</span> מתנודד בתוך החדר החסום שבין הקווים האפורים <span class=\"math math-inline\" dir=\"ltr\">\\(y=-1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span></span> (כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=1\\)</span>),</span> והגורם <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1x\\)</span> הולך לאפס. המכפלה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{\\sin(2x)}{x}\\)</span> נלכדת מהקו הירוק <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac1k\\)</span> והלאה לגמרי בתוך הרצועה האדומה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-k,k)\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> ואת <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ועקבו אחרי האיברים.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.4,&quot;xmax&quot;:13,&quot;ymin&quot;:-1.2,&quot;ymax&quot;:1.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;k&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;k=0.25&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.1,&quot;max&quot;:0.8,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=3&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:12,&quot;step&quot;:1}},{&quot;id&quot;:&quot;c&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;c(x)=\\\\sin(2\\\\cdot x)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{\\\\sin(2\\\\cdot x)}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;u&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=k&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=-k&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;w&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=\\\\frac{1}{k}&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pn&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: רשמו את שתי ההגדרות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: רשמו את שתי ההגדרות</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> סדרה אפסה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\to 0\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span></span> סדרה חסומה. לפי הגדרה 2.15, קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|c_n|&lt;M\\)</span>.</span></p></div></div>"},{"title":"רמז 2: טריק ה-$\\frac{\\varepsilon}{M}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: טריק <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{M}\\)</span></span></p><div class=\"callout-body\"><p>אנחנו רוצים <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b_n c_n|&lt;\\varepsilon\\)</span>.</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|c_n|&lt;M\\)</span>,</span></span> על ידי בחירת מקום שבו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b_n|&lt;\\frac{\\varepsilon}{M}\\)</span>,</span> החסם <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> יצטמצם!</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נבחר חסם חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> עבור הסדרה החסומה <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|c_n|&lt;M\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> נפעיל את הגדרת הגבול על הסדרה האפסה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> עם הרדיוס <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{M}&gt;0\\)</span>,</span> ונקבל שמאותו מקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b_n c_n|=|b_n|\\,|c_n|&lt;\\frac{\\varepsilon}{M}\\cdot M=\\varepsilon\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: תרגום תנאי החסימות.</strong> תהי <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> סדרה אפסה (כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}b_n=0\\)</span>),</span> ותהי <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> סדרה חסומה. לפי הגדרת סדרה חסומה (הגדרה 2.15), קיים מספר <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|c_n|&lt;M.\\]</div>\n<p><strong>שלב 2: שימוש באפסות עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon'=\\frac{\\varepsilon}{M}\\)</span>.</span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{M}&gt;0\\)</span>.</span> לפי הגדרת הגבול (הגדרה 2.9) עבור הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> המתכנסת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ועבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon'=\\frac{\\varepsilon}{M}\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|b_n-0|=|b_n|&lt;\\frac{\\varepsilon}{M}.\\]</div>\n<p><em>למה?</em> אנחנו דורשים מהסדרה האפסה לרדת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{M}\\)</span></span> (ולא סתם מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>),</span></span> כדי שאחרי הכפלה בחסם <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> התוצאה הסופית תצא קטנה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></span></p>\n<p><strong>שלב 3: הערכת המכפלה.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|c_n|&lt;M\\)</span></span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le |b_n|&lt;\\frac{\\varepsilon}{M}\\)</span>,</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|b_n c_n - 0|=|b_n|\\cdot|c_n|\\le |b_n|\\cdot M&lt;\\frac{\\varepsilon}{M}\\cdot M=\\varepsilon.\\]</div>\n<p>לכן לפי הגדרה 2.9 מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(b_n c_n)=0\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\((b_n c_n)\\)</span> היא סדרה אפסה.</p></div></div>","steps":["<p><strong>שלב 1: תרגום תנאי החסימות.</strong> תהי <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> סדרה אפסה (כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}b_n=0\\)</span>),</span> ותהי <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> סדרה חסומה. לפי הגדרת סדרה חסומה (הגדרה 2.15), קיים מספר <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|c_n|&lt;M.\\]</div>","<p><strong>שלב 2: שימוש באפסות עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon'=\\frac{\\varepsilon}{M}\\)</span>.</span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{M}&gt;0\\)</span>.</span> לפי הגדרת הגבול (הגדרה 2.9) עבור הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> המתכנסת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ועבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon'=\\frac{\\varepsilon}{M}\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|b_n-0|=|b_n|&lt;\\frac{\\varepsilon}{M}.\\]</div>\n<p><em>למה?</em> אנחנו דורשים מהסדרה האפסה לרדת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{M}\\)</span></span> (ולא סתם מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>),</span></span> כדי שאחרי הכפלה בחסם <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> התוצאה הסופית תצא קטנה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></span></p>","<p><strong>שלב 3: הערכת המכפלה.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|c_n|&lt;M\\)</span></span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le |b_n|&lt;\\frac{\\varepsilon}{M}\\)</span>,</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|b_n c_n - 0|=|b_n|\\cdot|c_n|\\le |b_n|\\cdot M&lt;\\frac{\\varepsilon}{M}\\cdot M=\\varepsilon.\\]</div>\n<p>לכן לפי הגדרה 2.9 מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(b_n c_n)=0\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\((b_n c_n)\\)</span> היא סדרה אפסה.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לנסות להפעיל אריתמטיקה של גבולות (&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim(b_n c_n)=0\\cdot\\lim c_n=0\\)</span>&quot;): אריתמטיקה מותרת <strong>רק</strong> כששני הגבולות קיימים, ואילו סדרה חסומה כמו <span class=\"math math-inline\" dir=\"ltr\">\\((-1)^n\\)</span> אינה מתכנסת כלל!</li><li>לשכוח לבדוק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span></span> לפני שמחלקים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> (אילו חסם היה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> אי אפשר היה לחלק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>;</span></span> לכן חשוב לקחת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span>).</span></li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשיש מהירות עלייה חיובית קבועה לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>,</span> הפונקציה חייבת לעבור לפחות את הקו הישר <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)+cx\\)</span> ולכן עולה לאינסוף. אבל אם המהירות רק חיובית ויכולה לדעוך לאפס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span></span> בלבד), הגרף יכול להתעגל מתחת לתקרה ולא לעלות לאינסוף לעולם!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשיש מהירות עלייה חיובית קבועה לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>,</span> הפונקציה חייבת לעבור לפחות את הקו הישר <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)+cx\\)</span> ולכן עולה לאינסוף. אבל אם המהירות רק חיובית ויכולה לדעוך לאפס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span></span> בלבד), הגרף יכול להתעגל מתחת לתקרה ולא לעלות לאינסוף לעולם!</p>\n<p><strong>תמונה בראש</strong>: בטענה (1), מטפס הרים מתחיל מגובה <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span> ועולה בקצב של לפחות <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> מטרים לקילומטר. אפילו אם יתעצל ולא יאיץ, הגובה שלו אחרי <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> קילומטרים יהיה לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)+cx\\)</span>,</span> שמגיע לאינסוף. בטענה (2), מטפס הרים תמיד מתקדם מעט למעלה, אבל בכל קילומטר הוא עושה צעד קטן בהרבה מקודמו (כמו חצי מטר, רבע מטר, שמינית מטר...) — אז הוא כל הזמן עולה, ובכל זאת לעולם לא יגיע אפילו למטר מעל נקודת ההתחלה!</p>\n<p><strong>עם מספרים</strong>: בטענה (1), אם <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\ge 0.5\\)</span></span> תמיד, אז <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=100\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(100)\\ge 1+50=51\\)</span>.</span> בטענה (2), לפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1-\\frac{1}{x+1}=\\frac{x}{x+1}\\)</span> יש נגזרת חיובית ממש <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{1}{(x+1)^2}&gt;0\\)</span> בכל מקום, אבל <span class=\"math math-inline\" dir=\"ltr\">\\(f(100)=\\frac{100}{101}&lt;1\\)</span> והגבול שלה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> לא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>.</span></p>\n<p><strong>משפט לגראנז׳</strong> מבטיח שהפרש הגובה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-f(0)\\)</span> שווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> כפול השיפוע באיזושהי נקודה באמצע.</p></div></details>","graphs":[{"title":"רואים את זה בגרף (סעיף 1)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (סעיף 1)</span></summary><div class=\"callout-body\"><p>טענה (1): הפונקציה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0.5x+\\sin(0.2x)\\)</span> בעלת שיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=0.5+0.2\\cos(0.2x)\\ge 0.3&gt;0\\)</span>,</span> ולכן היא שומרת על קצב עלייה חיובי קבוע ונמצאת מעל הקו הישר <span class=\"math math-inline\" dir=\"ltr\">\\(y=0.3x\\)</span> (אדום מקווקו) המטפס לאינסוף.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:12,&quot;ymin&quot;:-0.5,&quot;ymax&quot;:8}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=4&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.5,&quot;max&quot;:11,&quot;step&quot;:0.5}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=0.5\\\\cdot x+\\\\sin(0.2\\\\cdot x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0.3\\\\cdot x&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"},{"title":"רואים את זה בגרף (סעיף 2)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (סעיף 2)</span></summary><div class=\"callout-body\"><p>טענה (2) (דוגמה נגדית): הגרף הכחול <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1-\\frac{1}{x+1}\\)</span> עולה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> (הנגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{1}{(x+1)^2}&gt;0\\)</span>),</span> ובכל זאת הוא נתקע מתחת לתקרה האדומה המקווקוות <span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span> ולא שואף לאינסוף. הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> ימינה וראו את הגובה מתייצב מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:12,&quot;ymin&quot;:-0.2,&quot;ymax&quot;:1.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.5,&quot;max&quot;:11,&quot;step&quot;:0.5}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=1-\\\\frac{1}{x+1}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: קשר בין $f(x)-f(0)$ לבין $f'$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: קשר בין <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-f(0)\\)</span> לבין <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></p><div class=\"callout-body\"><p>הפעילו את משפט לגראנז׳ (משפט 8.6) על <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> מה זה נותן <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(\\xi)\\ge c\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: למה התנאי החלש $f'(x)>0$ עלול להיעצר בתקרה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: למה התנאי החלש <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span> עלול להיעצר בתקרה</p><div class=\"callout-body\"><p>חשבו על פונקציה עולה ממש שחסומה מלעיל (למשל פונקציה עם אסימפטוטה אופקית כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-\\frac{1}{x+1}\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(1-e^{-x}\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span>).</span> בדקו אם היא מקיימת את כל התנאים.</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>טענה (1) נכונה: מלגראנז׳ על <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-f(0)=f'(\\xi)x\\ge cx\\)</span>,</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\ge f(0)+cx\\to\\infty\\)</span>.</span> טענה (2) לא נכונה: <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1-\\frac{1}{x+1}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{1}{(x+1)^2}&gt;0\\)</span>,</span> אבל גבולה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\ne\\infty\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: טענה (1) נכונה, טענה (2) לא נכונה</strong></p>\n<p><strong>טענה (1): נכונה.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span></span> (כי היא רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span></span> (כי היא גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>).</span></span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(\\xi\\in(0,x)\\)</span> כך ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)-f(0)=f'(\\xi)(x-0)=f'(\\xi)x.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\xi&gt;0\\)</span>,</span></span> מהנתון מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(\\xi)\\ge c\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span></span> מתקבל לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)\\ge f(0)+cx.\\]</div>\n<p>נוכיח לפי הגדרת הגבול האינסופי (הגדרה 4.55) כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=\\infty\\)</span>:</span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\in\\mathbb R\\)</span>.</span> נבחר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[K=\\max\\left\\{1,\\frac{M-f(0)+1}{c}\\right\\}&gt;0\\]</div>\n<p>(החלוקה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> מותרת כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>).</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;K\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\frac{M-f(0)+1}{c}\\)</span>,</span> ולכן בהכפלה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)\\ge f(0)+cx&gt;f(0)+(M-f(0)+1)=M+1&gt;M.\\]</div>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=\\infty\\)</span>.</span></span></p>\n<p><em>למה?</em> משפט לגראנז׳ מתרגם את המידע על קצב השינוי המקומי <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\ge c\\)</span> לתמיכה גלובלית של קו ישר <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)+cx\\)</span> שדוחף את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> לאינסוף.</p>\n<p><strong>טענה (2): לא נכונה.</strong> נבחר את הפונקציה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=1-\\frac{1}{x+1},\\qquad x\\in[0,\\infty).\\]</div>\n<p>נבדוק את כל התנאים:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span> המכנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x+1\\ge 1\\ne 0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></li><li>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> הנגזרת היא:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{1}{(x+1)^2}&gt;0.\\]</div>\n<p>אף על פי כן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}f(x)=\\lim_{x\\to\\infty}\\left(1-\\frac{1}{x+1}\\right)=1-0=1\\ne\\infty.\\]</div>\n<p>(דוגמאות טובות נוספות הן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\arctan x\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-e^{-x}\\)</span>.)</span></p></div></div>","steps":["<p><strong>התשובה: טענה (1) נכונה, טענה (2) לא נכונה</strong></p>\n<p><strong>טענה (1): נכונה.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span></span> (כי היא רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span></span> (כי היא גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>).</span></span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(\\xi\\in(0,x)\\)</span> כך ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)-f(0)=f'(\\xi)(x-0)=f'(\\xi)x.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\xi&gt;0\\)</span>,</span></span> מהנתון מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(\\xi)\\ge c\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span></span> מתקבל לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)\\ge f(0)+cx.\\]</div>\n<p>נוכיח לפי הגדרת הגבול האינסופי (הגדרה 4.55) כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=\\infty\\)</span>:</span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\in\\mathbb R\\)</span>.</span> נבחר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[K=\\max\\left\\{1,\\frac{M-f(0)+1}{c}\\right\\}&gt;0\\]</div>\n<p>(החלוקה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> מותרת כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>).</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;K\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\frac{M-f(0)+1}{c}\\)</span>,</span> ולכן בהכפלה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)\\ge f(0)+cx&gt;f(0)+(M-f(0)+1)=M+1&gt;M.\\]</div>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=\\infty\\)</span>.</span></span></p>\n<p><em>למה?</em> משפט לגראנז׳ מתרגם את המידע על קצב השינוי המקומי <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\ge c\\)</span> לתמיכה גלובלית של קו ישר <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)+cx\\)</span> שדוחף את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> לאינסוף.</p>\n<p><strong>טענה (2): לא נכונה.</strong> נבחר את הפונקציה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=1-\\frac{1}{x+1},\\qquad x\\in[0,\\infty).\\]</div>\n<p>נבדוק את כל התנאים:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span> המכנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x+1\\ge 1\\ne 0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></li><li>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> הנגזרת היא:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{1}{(x+1)^2}&gt;0.\\]</div>\n<p>אף על פי כן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}f(x)=\\lim_{x\\to\\infty}\\left(1-\\frac{1}{x+1}\\right)=1-0=1\\ne\\infty.\\]</div>\n<p>(דוגמאות טובות נוספות הן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\arctan x\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-e^{-x}\\)</span>.)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב שפונקציה עולה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> שואפת תמיד לאינסוף (להתבלבל עם העובדה שלפונקציה עולה יש <strong>גבול סופי או <span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></strong>, ולא רק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>).</span></li><li>בטענה (1), לנסות להפעיל את לגראנז׳ בלי לנצל את רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span> כאן הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> היא בדיוק המקום שבו השתמשנו ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (בשונה מהגזירות שנדרשה רק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>).</span></span></li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"3":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> (10 נק׳) הוכיחו לפי שלילת ניסוח הגדרת הגבול בלשון <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon,\\delta\\)</span> (הגדרה 4.28) את הטענה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 3}\\frac{x+1}{x-1}\\ne 1,\\]</div>\n<p>כלומר שלא מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 3}\\frac{x+1}{x-1}=1\\)</span>.</span></p>\n<p><strong>הערה</strong>: אין להוכיח בדרך השלילה, אלא רק לפי שלילת ניסוח הגדרת הגבול בלשון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon,\\delta\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> המקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;e^x+e^{-x}\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>.</span> הוכיחו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מקבלת מינימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כדי להראות לפי השלילה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon,\\delta\\)</span> שהגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=3\\)</span></span> אינו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> מראים שיש &quot;מרחק כשל&quot; קבוע (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span>)</span> כך שבכל סביבה קטנה של <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> יש נקודה שבה ערך הפונקציה רחוק <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בלפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כדי להראות לפי השלילה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon,\\delta\\)</span> שהגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=3\\)</span></span> אינו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> מראים שיש &quot;מרחק כשל&quot; קבוע (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span>)</span> כך שבכל סביבה קטנה של <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> יש נקודה שבה ערך הפונקציה רחוק <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בלפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: חבר אומר לכם: &quot;אם תתקרב מספיק <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>,</span></span> הפונקציה תיכנס לכל רצועה דקה סביב <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>&quot;. כדי לשלול את ההבטחה הזו בלי &quot;הוכחה בשלילה&quot;, אתם פשוט מציבים רצועה אחת של רוחב <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> סביב הגובה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> (בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>),</span></span> ומראים שגם אם הוא יקטין את הסביבה סביב <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> לכמה קטנה שירצה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span>),</span> בצעד קטן שמאלה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> הפונקציה תמיד נמצאת <strong>מעל <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></strong>, כלומר מחוץ לרצועה!</p>\n<p><strong>עם מספרים</strong>: נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span>.</span> עבור כל רוחב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span>,</span> נזוז שמאלה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> בחצי <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\min\\{\\delta,1\\}\\)</span>:</span></span> למשל עבור <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=0.4\\)</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=3-0.2=2.8\\)</span>.</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3.8}{1.8}\\approx 2.11\\)</span>,</span> שהמרחק שלו <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.11&gt;1\\)</span>.</span></p>\n<p><strong>שלילת הגדרת הגבול</strong> הופכת &quot;לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> כך שלכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>...</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(&lt;\\varepsilon\\)</span>&quot; ל-&quot;<strong>קיים</strong> <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך ש<strong>לכל</strong> <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> <strong>קיימת</strong> נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\)</span> בסביבה הנקובה שבה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ge\\varepsilon_0\\)</span>&quot;.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול מתקרב אל הנקודה הירוקה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((3,2)\\)</span>,</span> ולא אל הגובה המוצע <span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span> (הקו האפור המקווקו). הרצועה סביב <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ברדיוס <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span> נגמרת בקו האדום המקווקו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=2\\)</span>.</span> הזיזו את המחוון <span class=\"math math-inline\" dir=\"ltr\">\\(d\\)</span> (המייצג את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span>)</span> הכי קרוב שתרצו <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span></span> הנקודה האדומה <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta=3-\\frac12 d\\)</span> תמיד נשארת בתוך חלון <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> שמאלה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>,</span></span> אבל גובהה תמיד <strong>מעל</strong> הקו האדום <span class=\"math math-inline\" dir=\"ltr\">\\(y=2\\)</span> (מרחק גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>)!</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:1.3,&quot;xmax&quot;:4.7,&quot;ymin&quot;:-0.2,&quot;ymax&quot;:4.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;d=0.6&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:1,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{x+1}{x-1}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;b&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=3-d&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=3+d&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(3-0.5\\\\cdot d,f(3-0.5\\\\cdot d))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: רושמים מפורשות את השלילה הלוגית של הגדרה 4.28","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: רושמים מפורשות את השלילה הלוגית של הגדרה 4.28</p><div class=\"callout-body\"><p>הגדרה 4.28 <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 3}f(x)=1\\)</span></span> אומרת: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> המקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;|x-3|&lt;\\delta\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-1|&lt;\\varepsilon\\)</span>.</span> מהו השלילה של משפט זה? (הכמתים מתחלפים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\exists\\varepsilon_0&gt;0\\;\\forall\\delta&gt;0\\;\\exists x_\\delta\\)</span>.)</span></span></p></div></div>"},{"title":"רמז 2: פישוט $\\left|\\frac{x+1}{x-1}-1\\right|$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: פישוט <span class=\"math math-inline\" dir=\"ltr\">\\(\\left|\\frac{x+1}{x-1}-1\\right|\\)</span></p><div class=\"callout-body\"><p>עשו מכנה משותף: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left|\\frac{x+1}{x-1}-1\\right|=\\frac{2}{|x-1|}\\)</span>.</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> קרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> מצד שמאל <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(2&lt;x&lt;3\\)</span>),</span> מה אפשר לומר על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-1|\\)</span>?</span></p></div></div>"},{"title":"רמז 3: בחירת $\\varepsilon_0$ ו-$x_\\delta$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\)</span></span></p><div class=\"callout-body\"><p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x-1&lt;2\\)</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2&lt;x&lt;3\\)</span>,</span> מקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{|x-1|}&gt;1\\)</span>!</span> לכן נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span>,</span> ולכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta=3-\\frac12\\min\\{\\delta,1\\}\\)</span>.</span> בדקו את כל התנאים.</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ננסח ישירות את שלילת הגדרה 4.28 עבור הגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>:</span> צריך למצוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> תימצא נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\)</span> בתחום ההגדרה עם <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;|x_\\delta-3|&lt;\\delta\\)</span> ועם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x_\\delta)-1|\\ge\\varepsilon_0\\)</span>.</span> נפשט <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{|x-1|}\\)</span>,</span></span> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta=3-\\frac12\\min\\{\\delta,1\\}\\)</span>,</span></span> ונראה שהביטוי גדול ממש <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: שלילת ניסוח הגדרת הגבול (הגדרה 4.28).</strong> נסמן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{x+1}{x-1}\\)</span> (מוגדרת לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 1\\)</span>).</span> כדי להוכיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 3}f(x)\\ne 1\\)</span></span> לפי שלילת הגדרה 4.28 (ללא הוכחה בשלילה), עלינו להראות:</p>\n<p>קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\ne 1\\)</span> המקיימת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;|x_\\delta-3|&lt;\\delta\\qquad\\text{וגם}\\qquad\\left|\\frac{x_\\delta+1}{x_\\delta-1}-1\\right|\\ge\\varepsilon_0.\\]</div>\n<p>(זוהי השלילה הלוגית של הטענה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מוגדרת בסביבה נקובה של <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> ולכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> שעבורו <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;|x-3|&lt;\\delta\\)</span> גורר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-1|&lt;\\varepsilon\\)</span>.)</span></p>\n<p><strong>שלב 2: בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span> ונקודה מתאימה לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span>.</span></strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1&gt;0\\)</span>.</span></p>\n<p>יהי <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כלשהו. נגדיר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_\\delta=3-\\frac12\\min\\{\\delta,1\\}.\\]</div>\n<p><strong>שלב 3: בדיקת כל הדרישות על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\)</span>.</span></strong></p>\n<ol><li><em>שייכות לתחום ולסביבה הנקובה:</em> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\min\\{\\delta,1\\}\\le 1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac12\\min\\{\\delta,1\\}\\le\\frac12\\)</span>,</span> ולכן:</li></ol>\n<div class=\"math math-display\" dir=\"ltr\">\\[2.5\\le x_\\delta&lt;3.\\]</div>\n<p>בפרט <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\ne 1\\)</span> (הפונקציה מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\)</span>),</span></span> ומתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;|x_\\delta-3|=\\frac12\\min\\{\\delta,1\\}&lt;\\min\\{\\delta,1\\}\\le\\delta.\\]</div>\n<ol start=\"2\"><li><em>בדיקת המרחק <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>:</span></span></em> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.5\\le x_\\delta&lt;3\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.5\\le x_\\delta-1&lt;2\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;|x_\\delta-1|&lt;2\\)</span>.</span> נפשט ונעריך:</li></ol>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{x_\\delta+1}{x_\\delta-1}-1\\right|=\\left|\\frac{x_\\delta+1-(x_\\delta-1)}{x_\\delta-1}\\right|=\\frac{2}{|x_\\delta-1|}&gt;\\frac{2}{2}=1=\\varepsilon_0.\\]</div>\n<p><em>למה?</em> אם היינו זזים ימינה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> (אל מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>),</span> המכנה <span class=\"math math-inline\" dir=\"ltr\">\\(x-1\\)</span> היה גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> והיינו מקבלים רק שבר קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (שעדיין היה מספיק עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=\\frac12\\)</span>,</span> אבל תזוזה שמאלה אל מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> נותנת מנה גדולה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ממש ובקלות).</p>\n<p>לכן שלילת הגדרה 4.28 מתקיימת, ומוכח כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 3}\\frac{x+1}{x-1}\\ne 1\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: שלילת ניסוח הגדרת הגבול (הגדרה 4.28).</strong> נסמן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{x+1}{x-1}\\)</span> (מוגדרת לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 1\\)</span>).</span> כדי להוכיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 3}f(x)\\ne 1\\)</span></span> לפי שלילת הגדרה 4.28 (ללא הוכחה בשלילה), עלינו להראות:</p>\n<p>קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\ne 1\\)</span> המקיימת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;|x_\\delta-3|&lt;\\delta\\qquad\\text{וגם}\\qquad\\left|\\frac{x_\\delta+1}{x_\\delta-1}-1\\right|\\ge\\varepsilon_0.\\]</div>\n<p>(זוהי השלילה הלוגית של הטענה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מוגדרת בסביבה נקובה של <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> ולכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> שעבורו <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;|x-3|&lt;\\delta\\)</span> גורר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-1|&lt;\\varepsilon\\)</span>.)</span></p>","<p><strong>שלב 2: בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span> ונקודה מתאימה לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span>.</span></strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1&gt;0\\)</span>.</span></p>\n<p>יהי <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כלשהו. נגדיר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_\\delta=3-\\frac12\\min\\{\\delta,1\\}.\\]</div>","<p><strong>שלב 3: בדיקת כל הדרישות על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\)</span>.</span></strong></p>\n<ol><li><em>שייכות לתחום ולסביבה הנקובה:</em> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\min\\{\\delta,1\\}\\le 1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac12\\min\\{\\delta,1\\}\\le\\frac12\\)</span>,</span> ולכן:</li></ol>\n<div class=\"math math-display\" dir=\"ltr\">\\[2.5\\le x_\\delta&lt;3.\\]</div>\n<p>בפרט <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\ne 1\\)</span> (הפונקציה מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta\\)</span>),</span></span> ומתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;|x_\\delta-3|=\\frac12\\min\\{\\delta,1\\}&lt;\\min\\{\\delta,1\\}\\le\\delta.\\]</div>\n<ol start=\"2\"><li><em>בדיקת המרחק <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>:</span></span></em> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.5\\le x_\\delta&lt;3\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.5\\le x_\\delta-1&lt;2\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;|x_\\delta-1|&lt;2\\)</span>.</span> נפשט ונעריך:</li></ol>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{x_\\delta+1}{x_\\delta-1}-1\\right|=\\left|\\frac{x_\\delta+1-(x_\\delta-1)}{x_\\delta-1}\\right|=\\frac{2}{|x_\\delta-1|}&gt;\\frac{2}{2}=1=\\varepsilon_0.\\]</div>\n<p><em>למה?</em> אם היינו זזים ימינה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> (אל מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>),</span> המכנה <span class=\"math math-inline\" dir=\"ltr\">\\(x-1\\)</span> היה גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> והיינו מקבלים רק שבר קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (שעדיין היה מספיק עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=\\frac12\\)</span>,</span> אבל תזוזה שמאלה אל מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> נותנת מנה גדולה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ממש ובקלות).</p>\n<p>לכן שלילת הגדרה 4.28 מתקיימת, ומוכח כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 3}\\frac{x+1}{x-1}\\ne 1\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להוכיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 3}\\frac{x+1}{x-1}=2\\)</span></span> ואז לומר &quot;נניח בשלילה שהגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> לפי יחידות הגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2=1\\)</span>,</span> סתירה&quot;: ההערה בשאלה אוסרת מפורשות הוכחה בדרך השלילה ודורשת ישירות את שלילת הנוסחה עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\exists\\varepsilon_0\\,\\forall\\delta\\,\\exists x\\)</span>.</span></li><li>לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(x_\\delta=3-\\frac{\\delta}{2}\\)</span> בלי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\min\\{\\delta,1\\}\\)</span>:</span> אז עבור <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=4\\)</span> הנקודה הייתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_4=1\\)</span>,</span> שבה הפונקציה כלל אינה מוגדרת!</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^x+e^{-x}\\)</span></span> מזנק לאינסוף גם בימין וגם בשמאל, הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> (שתמיד גדולה ממנו) חייבת להיות גבוהה מאוד בשני הקצוות — ולכן את הנקודה הנמוכה ביותר שלה היא מוכרחה לקבל באיזה קטע סגור באמצע.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^x+e^{-x}\\)</span></span> מזנק לאינסוף גם בימין וגם בשמאל, הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> (שתמיד גדולה ממנו) חייבת להיות גבוהה מאוד בשני הקצוות — ולכן את הנקודה הנמוכה ביותר שלה היא מוכרחה לקבל באיזה קטע סגור באמצע.</p>\n<p><strong>תמונה בראש</strong>: קערה עמוקה שתחתיתה המשוערת <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span> נמצאת בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span> ודפנות הקערה (מעבר למרחק <span class=\"math math-inline\" dir=\"ltr\">\\(R\\)</span> מסוים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span></span> כבר עולות לגבהים גדולים בהרבה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>.</span></span> מותר לקצוץ את הדפנות הרחוקות שבהן הגובה כבר גבוה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>:</span></span> המינימום של החלק הסגור שנשאר באמצע נמוך או שווה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>,</span></span> ולכן הוא נמוך מכל הישר כולו!</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הגבול התחתון הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^0+e^0=2\\)</span>.</span> אם נניח <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=5\\)</span>,</span></span> אז ברגע <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\ge 2\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{|x|}+e^{-|x|}&gt;e^2\\approx 7.39&gt;5=f(0)\\)</span>.</span> לכן המינימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([-2,2]\\)</span> (שקיים לפי ויירשטראס) קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5\\)</span>,</span></span> והוא המינימום על כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></p>\n<p><strong>מקבלת מינימום <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span></strong> פירושו שקיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in\\mathbb R\\)</span> שעבורה <span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> ללא יוצא מן הכלל.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול הוא דוגמה לפונקציה רציפה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^x+e^{-x}+0.5\\cos(2x)+1\\)</span> שיושבת תמיד מעל העקומה האדומה המקווקוות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=e^x+e^{-x}\\)</span>.</span> הקו הירוק המקווקו הוא הגובה <span class=\"math math-inline\" dir=\"ltr\">\\(y=f(0)\\)</span> (הנקודה הירוקה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,f(0))\\)</span>),</span> והקווים האפורים מסמנים את הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span> שמחוצה לו <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span> תמיד מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>:</span> לכן המינימום על <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span> הוא המינימום על כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>!</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-2.8,&quot;xmax&quot;:2.8,&quot;ymin&quot;:0,&quot;ymax&quot;:11}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=e^x+e^{-x}+0.5\\\\cdot\\\\cos(2\\\\cdot x)+1&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=e^x+e^{-x}&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;h&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=3.5&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=-1.26&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1.26&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,3.5)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: קישור בין הערך ב-$0$ לחלק הרחוק","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: קישור בין הערך <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> לחלק הרחוק</p><div class=\"callout-body\"><p>נשתמש בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> כנקודת ייחוס: בערך <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)&gt;e^0+e^0=2\\)</span>.</span> מתי <span class=\"math math-inline\" dir=\"ltr\">\\(e^{|x|}\\)</span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: קטימת $\\mathbb R$ לקטע סגור $[-R,R]$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: קטימת <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> לקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span></p><div class=\"callout-body\"><p>אם תמצאו <span class=\"math math-inline\" dir=\"ltr\">\\(R&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(|x|&gt;R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;f(0)\\)</span>,</span> מדוע די למצוא מינימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>?</span></p></div></div>"},{"title":"רמז 3: ויירשטראס השני על $[-R,R]$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: ויירשטראס השני על <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span></p><div class=\"callout-body\"><p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>,</span> ולכן לפי משפט 5.37 מקבלת בו מינימום בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[-R,R]\\)</span>.</span> השוו את <span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span></span> ומכאן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> שמחוץ <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>.</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ניקח כגובה השוואה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)&gt;2\\)</span>,</span> ונבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(R=\\ln(f(0))&gt;0\\)</span>:</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> מחוץ <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span></span> (ולמעשה לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\ge R\\)</span>),</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;e^x+e^{-x}&gt;e^{|x|}\\ge f(0)\\)</span>.</span> כעת נפעיל את המשפט השני של ויירשטראס (משפט 5.37) על הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span> כדי לקבל נקודת מינימום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[-R,R]\\)</span>,</span> ונראה שהיא מינימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: מציאת קטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span> שמחוצה לו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;f(0)\\)</span>.</span></strong> מהנתון עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(0)&gt;e^0+e^0=2&gt;1.\\]</div>\n<p>לכן המספר <span class=\"math math-inline\" dir=\"ltr\">\\(R=\\ln(f(0))\\)</span> מוגדר ומקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(R&gt;\\ln 2&gt;0\\)</span>.</span></p>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> המקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|&gt;R\\)</span>,</span> יש לשים לב שאחד משני המספרים <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> או <span class=\"math math-inline\" dir=\"ltr\">\\(-x\\)</span> שווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\)</span></span> והשני שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-|x|\\)</span>.</span></span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span></span> עולה ממש וחיובית תמיד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(e^{-|x|}&gt;0\\)</span>),</span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)&gt;e^x+e^{-x}=e^{|x|}+e^{-|x|}&gt;e^{|x|}&gt;e^R=e^{\\ln(f(0))}=f(0).\\]</div>\n<p><em>למה?</em> כל ערך של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> שנמצא מחוץ לקטע <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span> כבר גבוה ממש <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>,</span></span> כך שהמינימום העולמי של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> (שחייב להיות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\le f(0)\\)</span>)</span> לעולם לא יכול להסתתר מחוץ לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>.</span></p>\n<p><strong>שלב 2: קיום מינימום על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span> ובפרט היא רציפה בקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>.</span> לפי המשפט השני של ויירשטראס (משפט 5.37), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[-R,R]\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[-R,R]\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(c)\\le f(x).\\]</div>\n<p><strong>שלב 3: הוכחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> היא נקודת מינימום בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></strong> נבדוק עבור כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[-R,R]\\)</span>,</span> אז כבר ידוע <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x)\\)</span>.</span></span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\notin[-R,R]\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|&gt;R\\)</span>,</span> אז כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\in[-R,R]\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(0)\\)</span>,</span> ומשלב 1 נובע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)&lt;f(x)\\)</span>.</span> ביחד, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(0)&lt;f(x)\\)</span>.</span></li></ul>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x)\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת מינימום <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>).</span></p></div></div>","steps":["<p><strong>שלב 1: מציאת קטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span> שמחוצה לו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;f(0)\\)</span>.</span></strong> מהנתון עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(0)&gt;e^0+e^0=2&gt;1.\\]</div>\n<p>לכן המספר <span class=\"math math-inline\" dir=\"ltr\">\\(R=\\ln(f(0))\\)</span> מוגדר ומקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(R&gt;\\ln 2&gt;0\\)</span>.</span></p>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> המקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|&gt;R\\)</span>,</span> יש לשים לב שאחד משני המספרים <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> או <span class=\"math math-inline\" dir=\"ltr\">\\(-x\\)</span> שווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\)</span></span> והשני שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-|x|\\)</span>.</span></span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span></span> עולה ממש וחיובית תמיד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(e^{-|x|}&gt;0\\)</span>),</span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)&gt;e^x+e^{-x}=e^{|x|}+e^{-|x|}&gt;e^{|x|}&gt;e^R=e^{\\ln(f(0))}=f(0).\\]</div>\n<p><em>למה?</em> כל ערך של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> שנמצא מחוץ לקטע <span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span> כבר גבוה ממש <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>,</span></span> כך שהמינימום העולמי של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> (שחייב להיות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\le f(0)\\)</span>)</span> לעולם לא יכול להסתתר מחוץ לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>.</span></p>","<p><strong>שלב 2: קיום מינימום על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span> ובפרט היא רציפה בקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([-R,R]\\)</span>.</span> לפי המשפט השני של ויירשטראס (משפט 5.37), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[-R,R]\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[-R,R]\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(c)\\le f(x).\\]</div>","<p><strong>שלב 3: הוכחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> היא נקודת מינימום בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></strong> נבדוק עבור כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[-R,R]\\)</span>,</span> אז כבר ידוע <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x)\\)</span>.</span></span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\notin[-R,R]\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|&gt;R\\)</span>,</span> אז כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\in[-R,R]\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(0)\\)</span>,</span> ומשלב 1 נובע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)&lt;f(x)\\)</span>.</span> ביחד, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(0)&lt;f(x)\\)</span>.</span></li></ul>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x)\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת מינימום <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>).</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לטעון ש-&quot;אם <span class=\"math math-inline\" dir=\"ltr\">\\(f&gt;g\\)</span> <span class=\"nobr\">ול-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> יש מינימום, אז <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> יש מינימום&quot;: זה לא נכון! למשל קחו <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=0\\)</span> (שיש לה מינימום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^x&gt;0\\)</span></span> (שאינה מקבלת מינימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>).</span></span> הסיבה שכאן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> יש מינימום היא שהחסם התחתון <span class=\"math math-inline\" dir=\"ltr\">\\(e^x+e^{-x}\\)</span> שואף ל-<strong><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></strong> בשני הקצוות, לא סתם שיש לו מינימום.</li><li>להשוות רק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span></span> ולשכוח לבדוק גם את הצד השלילי <span class=\"math math-inline\" dir=\"ltr\">\\(x\\to-\\infty\\)</span> (ואז <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> הייתה יכולה לרדת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> או <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span></span> משמאל).</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"4":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) — רק למי שלמד/ה את הקורס בסמסטר 2024א/ב/ג</p>\n<p><strong>א.</strong> (10 נק׳) הוכיחו או הפריכו: תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה חיובית ומתכנסת, ונסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L\\)</span>.</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}L^n\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) הוכיחו או הפריכו: הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{e^{-x^2}-\\cos x}{x^2}\\)</span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\"><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to 1\\)</span>,</span></span> החזקה <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-ית של <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נשארת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> הוא צורה <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> שיכולה לסטות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ולהגיע למשל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></span> (או לכל מספר אחר!).</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to 1\\)</span>,</span></span> החזקה <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-ית של <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נשארת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> הוא צורה <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> שיכולה לסטות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ולהגיע למשל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></span> (או לכל מספר אחר!).</p>\n<p><strong>תמונה בראש</strong>: תחרות בין איברים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> שמתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לבין המעריך <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שמושך אותם למעלה. אם שמים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> בדיוק <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(L^n=1^n\\)</span>),</span> אין מה למתוח ונשארים על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> אבל אם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> עומדת טיפה מעל <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> (בשיעור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span>),</span> המתיחה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> הופכת את הסדרה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\approx 2.718\\)</span></span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>!</span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span>.</span> זו סדרה חיובית שמתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>,</span></span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}L^n=\\lim_{n\\to\\infty}1^n=1\\)</span>.</span> אבל בצד שמאל, <span class=\"math math-inline\" dir=\"ltr\">\\((1+\\frac1n)^n\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\approx 2.718\\ne 1\\)</span>!</span></span> (אפשר גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\to 1\\)</span>,</span> שנותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=2\\ne 1\\)</span>.)</span></p>\n<p><strong>משפט ארימתטיקה של גבולות</strong> אינו מאפשר &quot;להציב גבול בבסיס כשהמעריך עצמו תלוי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> ושואף לאינסוף&quot; — זוהי צורת אי-ודאות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הנקודות הכחולות הן איברי הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> שיורדות לכיוון <span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span> (הקו הירוק). לכן <span class=\"math math-inline\" dir=\"ltr\">\\(L^n=1^n=1\\)</span> תמיד. אבל החזקה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=(1+\\frac1n)^n\\)</span> (באדום) מטפסת לכיוון <span class=\"math math-inline\" dir=\"ltr\">\\(e\\approx 2.7183\\)</span> (הקו האדום המקווקו), ולא אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>!</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> קדימה וראו את הפער.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.4,&quot;xmax&quot;:15.5,&quot;ymin&quot;:0.5,&quot;ymax&quot;:3.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:15,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=1+\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\left(1+\\\\frac{1}{x}\\\\right)^x&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;l1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;le&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2.7183&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;pp&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,g(n))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איזה גבול $L$ עושה בעיות בחזקה ה-$n$-ית","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איזה גבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> עושה בעיות בחזקה <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-ית</p><div class=\"callout-body\"><p>אם <span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;1\\)</span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^n\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(L^n\\)</span> שואפים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>,</span></span> ואם <span class=\"math math-inline\" dir=\"ltr\">\\(0\\le L&lt;1\\)</span> שתיהן שואפות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> מה קורה <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: דוגמת הגבול של $e$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: דוגמת הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></p><div class=\"callout-body\"><p>בחרו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> (או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span>).</span> חשבו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>,</span> את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim L^n\\)</span> ואת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim (a_n)^n\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>הטענה לא נכונה. עבור גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>,</span> מתקבלת צורת האי-ודאות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span>.</span> ניקח כדוגמה נגדית את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span>:</span> היא חיובית ומתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>,</span></span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}L^n=\\lim_{n\\to\\infty}1^n=1\\)</span>,</span> ואילו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)^n=e\\ne 1\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: הדוגמה הנגדית ובדיקת התנאים.</strong> נבחר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n=1+\\frac1n.\\]</div>\n<p>הסדרה חיובית (לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1&gt;0\\)</span>)</span> ומתכנסת לגבול:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)=1.\\]</div>\n<p><strong>שלב 2: חישוב שני האגפים והשוואה.</strong></p>\n<ul><li>באגף ימין, כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>,</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L^n=1^n=1\\)</span>,</span> ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}L^n=1.\\]</div>\n<ul><li>באגף שמאל, מהגדרת המספר <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> כגבול הסדרה המונוטונית והחסומה <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1+\\frac1n\\right)^n\\)</span> (משפט 3.16; פרק 6.5):</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)^n=e\\approx 2.718\\ne 1.\\]</div>\n<p><em>למה?</em> כאשר המעריך <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שואף לאינסוף, אי אפשר להחליף את הבסיס <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בגבולו <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> כשהגבול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> — ההתקרבות של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בקצב <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span> מתאזנת מול <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ויוצרת את הקבוע <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n\\ne\\lim_{n\\to\\infty}L^n\\)</span>,</span></span> והטענה הופרכה.</p></div></div>","steps":["<p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: הדוגמה הנגדית ובדיקת התנאים.</strong> נבחר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n=1+\\frac1n.\\]</div>\n<p>הסדרה חיובית (לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1&gt;0\\)</span>)</span> ומתכנסת לגבול:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)=1.\\]</div>","<p><strong>שלב 2: חישוב שני האגפים והשוואה.</strong></p>\n<ul><li>באגף ימין, כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>,</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L^n=1^n=1\\)</span>,</span> ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}L^n=1.\\]</div>\n<ul><li>באגף שמאל, מהגדרת המספר <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> כגבול הסדרה המונוטונית והחסומה <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1+\\frac1n\\right)^n\\)</span> (משפט 3.16; פרק 6.5):</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)^n=e\\approx 2.718\\ne 1.\\]</div>\n<p><em>למה?</em> כאשר המעריך <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שואף לאינסוף, אי אפשר להחליף את הבסיס <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בגבולו <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> כשהגבול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> — ההתקרבות של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בקצב <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span> מתאזנת מול <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ויוצרת את הקבוע <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n\\ne\\lim_{n\\to\\infty}L^n\\)</span>,</span></span> והטענה הופרכה.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להשתמש בכלל &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(a_n^{b_n}\\to L^M\\)</span>&quot; (טענה 6.15): כלל זה תקף <strong>רק</strong> כשהמעריך <span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span> שואף לגבול <strong>סופי</strong> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> לא <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n=n\\to\\infty\\)</span>!</span></span></li><li>לקחת סדרה כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac{1}{n^2}\\)</span>:</span> שם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\to 1=L^n\\)</span>,</span> כך שהיא דווקא מקיימת את השוויון ואינה מפריכה את הטענה.</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הפונקציה שואפת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12\\)</span>,</span> <span class=\"nobr\">ומ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> והלאה היא נמחצת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{x^2}\\)</span></span> — לכן היא חסומה לכל אורך הקטע.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הפונקציה שואפת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12\\)</span>,</span> <span class=\"nobr\">ומ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> והלאה היא נמחצת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2}{x^2}\\)</span></span> — לכן היא חסומה לכל אורך הקטע.</p>\n<p><strong>תמונה בראש</strong>: נבדוק אם הגרף בורח לאינסוף בקצה השמאלי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span> או בצד ימין <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>).</span> ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> הן <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x^2}\\)</span> והן <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x\\)</span> שוות בערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> וכדי לראות מי מנצח מול <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> נשתמש בכלל לופיטל פעם אחת — ומתברר שהיחס שואף בשקט <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12\\)</span>.</span></span> מימין <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> המונה לא עובר את <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> והמכנה <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> רק גדל, כך שהשבר יורד אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.1\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-0.01}-\\cos 0.1}{0.01}\\approx\\frac{0.99005-0.99500}{0.01}\\approx -0.495\\approx-\\frac12\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-1}-\\cos 1}{1}\\approx -0.172\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=10\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(10)|\\le\\frac{2}{100}=0.02\\)</span>.</span></p>\n<p><strong>המשפט הראשון של ויירשטראס</strong> מבטיח שפונקציה רציפה על קטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> היא בהכרח חסומה שם.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{e^{-x^2}-\\cos x}{x^2}\\)</span> מתקרב משמאל לקו המקווקו <span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span> אל החור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,-\\frac12)\\)</span>,</span> ומימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> נשאר כלוא בין הקווים האדומים המקווקווים <span class=\"math math-inline\" dir=\"ltr\">\\(y=\\frac{2}{x^2}\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=-\\frac{2}{x^2}\\)</span>.</span></span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> כדי לעקוב אחרי הערכים.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:5.5,&quot;ymin&quot;:-1.2,&quot;ymax&quot;:1.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=0.5&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:5,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{e^{-x^2}-\\\\cos(x)}{x^2}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;bu&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=\\\\frac{2}{x^2}&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;bd&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=-\\\\frac{2}{x^2}&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;w&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,-0.5)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(0, -1/2)&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: פיצול לשני חלקים","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: פיצול לשני חלקים</p><div class=\"callout-body\"><p>פצלו את <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span> ולקרן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></p></div></div>"},{"title":"רמז 2: הגבול ב-$0^+$ באמצעות כלל לופיטל","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: הגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span></span> באמצעות כלל לופיטל</p><div class=\"callout-body\"><p>גזרו פעם אחת מונה ומכנה (משפט 8.13) והפרידו את מנת הנגזרות: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{-2xe^{-x^2}+\\sin x}{2x}=-e^{-x^2}+\\frac{\\sin x}{2x}\\)</span>.</span> מהו הגבול לפי משפט 4.45?</p></div></div>"},{"title":"רמז 3: חסימות על $[1,\\infty)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: חסימות על <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></p><div class=\"callout-body\"><p>שימו לב שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;e^{-x^2}&lt;1\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos x|\\le 1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|e^{-x^2}-\\cos x|\\le 2\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפצל את <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span></span> <span class=\"nobr\">ול-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span> בעזרת גזירה אחת בכלל לופיטל (ומשפט 4.45) נמצא <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=-\\frac12\\)</span>,</span></span> נשלים ברציפות <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> ונסיק ממשפט ויירשטראס הראשון שהיא חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>.</span></span> על <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span> נראה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le\\frac{2}{x^2}\\le 2\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: חישוב הגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span>.</span></span></strong> בביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-x^2}-\\cos x}{x^2}\\)</span> המונה והמכנה גזירים ורציפים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> שניהם שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^0-\\cos 0=1-1=0\\)</span>),</span> ונגזרת המכנה היא <span class=\"math math-inline\" dir=\"ltr\">\\(2x\\ne 0\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></p>\n<p>נחשב את גבול מנת הנגזרות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{(e^{-x^2}-\\cos x)'}{(x^2)'}=\\frac{-2xe^{-x^2}+\\sin x}{2x}=-e^{-x^2}+\\frac12\\cdot\\frac{\\sin x}{x}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>,</span></span> מרציפות האקספוננט מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-e^{-x^2}\\to -1\\)</span>,</span> ולפי משפט 4.45 מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin x}{x}\\to 1\\)</span>.</span> לכן גבול מנת הנגזרות קיים ושווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1+\\frac12=-\\frac12\\)</span>.</span></span> לפי כלל לופיטל (משפט 8.13 בגרסה החד-צדדית):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{e^{-x^2}-\\cos x}{x^2}=-\\frac12.\\]</div>\n<p><em>למה?</em> לאחר פירוק השבר לשני מחוברים מתקבל הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin x}{x}\\)</span> הידוע ממשפט 4.45, כך שאין צורך לגזור פעם שנייה.</p>\n<p><strong>שלב 2: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>.</span></span></strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,1]\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=-\\frac12\\)</span>.</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span></span> (מנה של רציפות עם מכנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>)</span> ורציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}h(x)=-\\frac12=h(0)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> וממשפט ויירשטראס הראשון (משפט 5.35) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M_1\\)</span>.</span></p>\n<p><strong>שלב 3: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ge 1&gt;0\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;e^{-x^2}&lt;1\\)</span>,</span> וכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos x|\\le 1\\)</span>.</span> מאי-שוויון המשולש (משפט 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)|=\\frac{|e^{-x^2}-\\cos x|}{x^2}\\le\\frac{|e^{-x^2}|+|\\cos x|}{x^2}&lt;\\frac{1+1}{x^2}=\\frac{2}{x^2}\\le 2.\\]</div>\n<p><strong>שלב 4: סיכום.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\max\\{M_1,2\\}\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p></div></div>","steps":["<p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: חישוב הגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span>.</span></span></strong> בביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-x^2}-\\cos x}{x^2}\\)</span> המונה והמכנה גזירים ורציפים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> שניהם שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^0-\\cos 0=1-1=0\\)</span>),</span> ונגזרת המכנה היא <span class=\"math math-inline\" dir=\"ltr\">\\(2x\\ne 0\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></p>\n<p>נחשב את גבול מנת הנגזרות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{(e^{-x^2}-\\cos x)'}{(x^2)'}=\\frac{-2xe^{-x^2}+\\sin x}{2x}=-e^{-x^2}+\\frac12\\cdot\\frac{\\sin x}{x}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>,</span></span> מרציפות האקספוננט מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-e^{-x^2}\\to -1\\)</span>,</span> ולפי משפט 4.45 מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin x}{x}\\to 1\\)</span>.</span> לכן גבול מנת הנגזרות קיים ושווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1+\\frac12=-\\frac12\\)</span>.</span></span> לפי כלל לופיטל (משפט 8.13 בגרסה החד-צדדית):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{e^{-x^2}-\\cos x}{x^2}=-\\frac12.\\]</div>\n<p><em>למה?</em> לאחר פירוק השבר לשני מחוברים מתקבל הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin x}{x}\\)</span> הידוע ממשפט 4.45, כך שאין צורך לגזור פעם שנייה.</p>","<p><strong>שלב 2: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>.</span></span></strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,1]\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=-\\frac12\\)</span>.</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span></span> (מנה של רציפות עם מכנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>)</span> ורציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}h(x)=-\\frac12=h(0)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> וממשפט ויירשטראס הראשון (משפט 5.35) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M_1\\)</span>.</span></p>","<p><strong>שלב 3: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ge 1&gt;0\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;e^{-x^2}&lt;1\\)</span>,</span> וכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos x|\\le 1\\)</span>.</span> מאי-שוויון המשולש (משפט 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)|=\\frac{|e^{-x^2}-\\cos x|}{x^2}\\le\\frac{|e^{-x^2}|+|\\cos x|}{x^2}&lt;\\frac{1+1}{x^2}=\\frac{2}{x^2}\\le 2.\\]</div>","<p><strong>שלב 4: סיכום.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\max\\{M_1,2\\}\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לגזור פעם שנייה בכלל לופיטל מבלי לשים לב שאם מפצלים מראש את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-e^{-x^2}+\\frac{\\sin x}{2x}\\)</span>,</span> הצורה כבר אינה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac00\\)</span>!</span> (הפעלת לופיטל על ביטוי שאינו <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac00\\)</span> פוגעת בפתרון.)</li><li>להסתפק בגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span></span> בלי להשתמש במשפט ויירשטראס הראשון על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"5":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) — רק למי שלמד/ה את הקורס בסמסטר אחר (שנה 2023 או סמסטר 2025א)</p>\n<p><strong>א.</strong> (10 נק׳) הוכיחו או הפריכו: תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה חיובית ומתכנסת, ונסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L\\)</span>.</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}L^n\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) הוכיחו או הפריכו: הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{e^{-x^2}-\\cos x}{x^2}\\)</span> רציפה במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כאשר הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> של הבסיס שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> היא בצורת <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> ויכולה לשאוף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></span> (או <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>),</span></span> בעוד <span class=\"math math-inline\" dir=\"ltr\">\\(L^n=1^n=1\\)</span> נשאר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כאשר הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> של הבסיס שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> היא בצורת <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> ויכולה לשאוף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></span> (או <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>),</span></span> בעוד <span class=\"math math-inline\" dir=\"ltr\">\\(L^n=1^n=1\\)</span> נשאר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: דמיינו שאומרים &quot;הבסיס שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> אז תציבו <span class=\"math math-inline\" dir=\"ltr\">\\(1^n=1\\)</span>&quot;. זה עובד כשהחזקה קבועה, אבל כשהחזקה <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> עצמה צומחת לאינסוף, הסטייה הקטנה של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מתכפלת בגודל המעריך ויכולה להפיק מספר שונה לגמרי <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n&gt;0\\)</span>.</span> הגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}L^n=1\\)</span>.</span> אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)^n=e\\approx 2.718\\ne 1\\)</span>.</span></p>\n<p><strong>גבול אוילר <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>)</span></strong> הוא הערך שאליו שואפת הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1+\\frac1n\\right)^n\\)</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\to\\infty\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(e\\approx 2.718\\)</span>).</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> מתקרב אל <span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span> (קו ירוק מקווקו, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(L^n=1\\)</span> תמיד), ואילו <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=(1+\\frac1n)^n\\)</span> (באדום) מטפסת אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\approx 2.7183\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> קדימה וצפו בפער בין <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.4,&quot;xmax&quot;:15.5,&quot;ymin&quot;:0.5,&quot;ymax&quot;:3.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:15,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=1+\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\left(1+\\\\frac{1}{x}\\\\right)^x&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;l1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;le&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2.7183&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;pp&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,g(n))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איזה $L$ יוצר אי-ודאות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איזה <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> יוצר אי-ודאות</p><div class=\"callout-body\"><p>חשבו מה קורה <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span></span> (המקרה היחיד שבו <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> יכול לשאוף למספר שאינו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>).</span></p></div></div>"},{"title":"רמז 2: דוגמה מפורשת","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: דוגמה מפורשת</p><div class=\"callout-body\"><p>בדקו את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> (או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span>):</span> האם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span> ומתכנסת? מהו <span class=\"math math-inline\" dir=\"ltr\">\\(L^n\\)</span> ומהו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span>?</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>הטענה לא נכונה. ניקח את הסדרה החיובית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span>,</span> המתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>:</span></span> באגף ימין <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}1^n=1\\)</span>,</span> ואילו באגף שמאל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(1+\\frac1n)^n=e\\ne 1\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: דוגמה נגדית.</strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span> זו סדרה חיובית המתכנסת לגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>.</span></p>\n<p><strong>שלב 2: חישוב שני הגבולות.</strong></p>\n<ul><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}L^n=\\lim_{n\\to\\infty}1^n=1\\)</span>.</span></li><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)^n=e\\)</span>.</span></li></ul>\n<p><em>למה?</em> כאשר הגבול של הבסיס הוא <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> והמעריך <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שואף לאינסוף, יש תחרות מסוג <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> ואי אפשר להחליף את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\ne 1\\)</span>,</span></span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n\\ne\\lim_{n\\to\\infty}L^n\\)</span>.</span></p></div></div>","steps":["<p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: דוגמה נגדית.</strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span> זו סדרה חיובית המתכנסת לגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>.</span></p>","<p><strong>שלב 2: חישוב שני הגבולות.</strong></p>\n<ul><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}L^n=\\lim_{n\\to\\infty}1^n=1\\)</span>.</span></li><li><span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)^n=e\\)</span>.</span></li></ul>\n<p><em>למה?</em> כאשר הגבול של הבסיס הוא <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> והמעריך <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שואף לאינסוף, יש תחרות מסוג <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> ואי אפשר להחליף את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\ne 1\\)</span>,</span></span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n\\ne\\lim_{n\\to\\infty}L^n\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להניח שמותר להעביר גבול לבסיס בלי קשר למעריך, או לשכוח שלצורה <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> אין גבול אוניברסלי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></li><li>לקחת סדרה שמתכנסת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> או למספר <span class=\"math math-inline\" dir=\"ltr\">\\(&gt;1\\)</span> ולומר שיש להן &quot;גבול אחר&quot; (עבור <span class=\"math math-inline\" dir=\"ltr\">\\(L\\ne 1\\)</span> השוויון דווקא כן מתקיים, כולל במובן הרחב <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;1\\)</span>).</span></span></li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> אפשר לסתום את החור בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12\\)</span>,</span> <span class=\"nobr\">וכש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> גדל הפונקציה שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> — לכן היא רציפה על <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> עם גבול סופי באינסוף, ומכאן רציפה במידה שווה.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> אפשר לסתום את החור בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12\\)</span>,</span> <span class=\"nobr\">וכש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> גדל הפונקציה שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> — לכן היא רציפה על <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> עם גבול סופי באינסוף, ומכאן רציפה במידה שווה.</p>\n<p><strong>תמונה בראש</strong>: דמיינו כביש שמתחיל בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12\\)</span> (אחרי שסותמים נקודתית את החור של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>),</span> מתפתל קצת, ובסוף מתיישר לגובה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> לכל אורכו עד האופק. על החלק ההתחלתי הסופי משפט קנטור דואג שלא יהיו עליות תלולות מדי, ועל הזנב הרחוק הכביש כבר כמעט שטוח לגמרי על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0.01\\)</span></span> הערך הוא כמעט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-0.5\\)</span>.</span> <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=20\\)</span></span> והלאה מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le\\frac{2}{400}=0.005\\)</span>,</span> כך שהמרחק בין כל שתי נקודות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(20\\)</span></span> והלאה קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.01\\)</span>.</span></span></p>\n<p><strong>רציפות במידה שווה</strong> אומרת שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> יש מרחק <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> אחד שמשרת את כל הנקודות בקטע יחד.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>העקומה הכחולה מתחילה ליד החור <span class=\"math math-inline\" dir=\"ltr\">\\((0,-\\frac12)\\)</span> ובצד ימין מתייצבת ונצמדת לאסימפטוטה האופקית <span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span> (אדומה מקווקוות). הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> כדי לבדוק שאין שום מקום שבו העקומה הופכת תלולה עד אינסוף או מתנודדת במהירות גדלה.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:7,&quot;ymin&quot;:-0.65,&quot;ymax&quot;:0.25}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=1&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:6.5,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{e^{-x^2}-\\\\cos(x)}{x^2}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;a0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,-0.5)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(0, -1/2)&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: גבולות בשני הקצוות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: גבולות בשני הקצוות</p><div class=\"callout-body\"><p>מצאו את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)\\)</span> (לופיטל + משפט 4.45) ואת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)\\)</span> (סנדוויץ׳).</p></div></div>"},{"title":"רמז 2: מעבר לקרן $[0,\\infty)$ ומשפט קנטור","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מעבר לקרן <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> ומשפט קנטור</p><div class=\"callout-body\"><p>השלימו את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=-\\frac12\\)</span>.</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\to 0\\)</span></span> באינסוף (מסקנת שאלה 48 ביחידה 5).</p></div></div>"},{"title":"רמז 3: חלוקה עם חפיפה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: חלוקה עם חפיפה</p><div class=\"callout-body\"><p>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> מצאו <span class=\"math math-inline\" dir=\"ltr\">\\(K&gt;1\\)</span> שמשם <span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span> (מכאן <span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)-h(y)|&lt;\\varepsilon\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\ge K\\)</span>).</span> על <span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span> הפעילו את קנטור (משפט 5.48) לקבלת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1\\)</span>,</span> ובחרו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{1,\\delta_1\\}\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נחשב בעזרת לופיטל את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=-\\frac12\\)</span> ונשלים ברציפות לפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span> נראה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> נפצל בעזרת <span class=\"math math-inline\" dir=\"ltr\">\\(K&gt;1\\)</span> שמשם <span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span> וקנטור על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span>,</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{1,\\delta_1\\}\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: השלמה ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>.</span></span></strong> כפי שחושב בכלל לופיטל (משפט 8.13 בגרסה החד-צדדית) ובמשפט 4.45:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{e^{-x^2}-\\cos x}{x^2}=\\lim_{x\\to 0^+}\\left(-e^{-x^2}+\\frac12\\cdot\\frac{\\sin x}{x}\\right)=-1+\\frac12=-\\frac12.\\]</div>\n<p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,\\infty)\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=-\\frac12\\)</span>.</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></p>\n<p>באינסוף, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;e^{-x^2}&lt;1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos x|\\le 1\\)</span>,</span></span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0\\le|h(x)|=\\frac{|e^{-x^2}-\\cos x|}{x^2}\\le\\frac{2}{x^2}\\xrightarrow[x\\to\\infty]{}0.\\]</div>\n<p>לפי משפט הסנדוויץ׳, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>.</span></p>\n<p><strong>שלב 2: טיפול בזנב ובקטע סגור (מסקנת שאלה 48 ביחידה 5).</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\to 0\\)</span></span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K&gt;1\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge K\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span> לכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\ge K\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|h(x)-h(y)|\\le|h(x)|+|h(y)|&lt;\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon.\\]</div>\n<p>על הקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה, ולכן לפי משפט קנטור (משפט 5.48) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)-h(y)|&lt;\\varepsilon\\)</span>.</span></p>\n<p><strong>שלב 3: בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> אחיד.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{1,\\delta_1\\}&gt;0\\)</span>.</span> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span>,</span> ובלי הגבלת הכלליות נניח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le K\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y&lt;x+\\delta\\le K+1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span>,</span> ומקנטור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;K\\)</span>,</span> אז גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\ge x&gt;K\\)</span>,</span> ולכן מהערכת הזנב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p><em>למה?</em> בחירת החפיפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([K,K+1]\\)</span></span> מבטיחה שנקודות במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לא יוכלו להיפרד משני עברי נקודת התפר: כל זוג כזה נמצא יחד בתוך <span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span> או יחד בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([K,\\infty)\\)</span>.</span></p>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה במידה שווה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לפי הגדרה 5.46.</p></div></div>","steps":["<p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: השלמה ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>.</span></span></strong> כפי שחושב בכלל לופיטל (משפט 8.13 בגרסה החד-צדדית) ובמשפט 4.45:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{e^{-x^2}-\\cos x}{x^2}=\\lim_{x\\to 0^+}\\left(-e^{-x^2}+\\frac12\\cdot\\frac{\\sin x}{x}\\right)=-1+\\frac12=-\\frac12.\\]</div>\n<p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,\\infty)\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=-\\frac12\\)</span>.</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></p>\n<p>באינסוף, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;e^{-x^2}&lt;1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos x|\\le 1\\)</span>,</span></span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0\\le|h(x)|=\\frac{|e^{-x^2}-\\cos x|}{x^2}\\le\\frac{2}{x^2}\\xrightarrow[x\\to\\infty]{}0.\\]</div>\n<p>לפי משפט הסנדוויץ׳, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>.</span></p>","<p><strong>שלב 2: טיפול בזנב ובקטע סגור (מסקנת שאלה 48 ביחידה 5).</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\to 0\\)</span></span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K&gt;1\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge K\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span> לכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\ge K\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|h(x)-h(y)|\\le|h(x)|+|h(y)|&lt;\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon.\\]</div>\n<p>על הקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה, ולכן לפי משפט קנטור (משפט 5.48) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)-h(y)|&lt;\\varepsilon\\)</span>.</span></p>","<p><strong>שלב 3: בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> אחיד.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{1,\\delta_1\\}&gt;0\\)</span>.</span> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span>,</span> ובלי הגבלת הכלליות נניח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le K\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y&lt;x+\\delta\\le K+1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span>,</span> ומקנטור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;K\\)</span>,</span> אז גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\ge x&gt;K\\)</span>,</span> ולכן מהערכת הזנב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p><em>למה?</em> בחירת החפיפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([K,K+1]\\)</span></span> מבטיחה שנקודות במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לא יוכלו להיפרד משני עברי נקודת התפר: כל זוג כזה נמצא יחד בתוך <span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span> או יחד בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([K,\\infty)\\)</span>.</span></p>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה במידה שווה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לפי הגדרה 5.46.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב שפונקציה רציפה וחסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> היא בהכרח רציפה במידה שווה (דוגמת נגד: <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(x^2)\\)</span> רציפה וחסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> ואינה במ״ש).</li><li>לשכוח את נקודת הקצה <span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span> או לחבר שני קטעים בלי חפיפה ביניהם.</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"6":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>נאמר שקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> <strong>צפופה</strong> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> אם לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span></span></p>\n<p>אם <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> צפופה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span></span> צפופה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span>,</span> ויש נקודה משותפת לשני הקטעים ומכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\cup J\\)</span></span> הוא קטע, אז:</p>\n<ol><li><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\cup J\\)</span>.</span></span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\cup J\\)</span>.</span></span></li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 1,2 ד. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כששני קטעים חופפים נפגשים ויוצרים קטע אחד ארוך, איחוד הנקודות הצפופות משניהם צפוף בכל הקטע המשותף — אבל שתי הקבוצות עדיין עלולות להיות זרות לגמרי בחיתוך!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כששני קטעים חופפים נפגשים ויוצרים קטע אחד ארוך, איחוד הנקודות הצפופות משניהם צפוף בכל הקטע המשותף — אבל שתי הקבוצות עדיין עלולות להיות זרות לגמרי בחיתוך!</p>\n<p><strong>תמונה בראש</strong>: שני שבילים <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span></span> שמתחברים בנקודה משותפת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span>.</span> על שביל <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> מפוזרות אבנים לבנות צפופות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>),</span> ועל שביל <span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span> מפוזרות אבנים שחורות צפופות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span>).</span> אם שמים את כל האבנים יחד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span>),</span> בין כל שני מקומות בשביל המחובר יש לפחות אבן אחת — אפילו אם מנקודה אחת בשביל <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> מסתכלים לנקודה בשביל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span>,</span> פשוט מסתכלים עד נקודת החיבור <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> שכבר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> ושם בטוח יש אבן לבנה! אבל בחיתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B\\)</span>,</span> אם אבנים לבנות ושחורות אף פעם לא יושבות באותו מקום, אין אף אבן משותפת.</p>\n<p><strong>עם מספרים</strong>: נניח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=[0,1.5]\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(J=[1,2.5]\\)</span> עם נקודה משותפת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p=1.2\\)</span>.</span> אם ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(x=0.5\\in I\\setminus J\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=2.1\\in J\\setminus I\\)</span>,</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(p=1.2\\)</span> יושבת ביניהם <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0.5&lt;1.2&lt;2.1\\)</span>):</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0.5,1.2]\\subseteq I\\)</span> בטוח יש איבר של <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> בין <span class=\"math math-inline\" dir=\"ltr\">\\(0.5\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.2\\)</span>,</span></span> וממילא הוא בין <span class=\"math math-inline\" dir=\"ltr\">\\(0.5\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.1\\)</span>!</span></span> אבל אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=J=\\mathbb R\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span>,</span></span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B=\\emptyset\\)</span>.</span></p>\n<p><strong>קטע</strong> מתאפיין בכך שאם שתי נקודות שייכות לו, כל הנקודות שביניהן שייכות לו.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> משמאל והקטע <span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span> מימין נפגשים סביב הנקודה הירוקה המשותפת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p=1.2\\)</span>.</span> גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(x=0.5\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\setminus J\\)</span></span> (הקו הכחול) <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y=2.1\\)</span></span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(J\\setminus I\\)</span></span> (הקו האדום), הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> נמצאת בהכרח ביניהם: לכן הפתח <span class=\"math math-inline\" dir=\"ltr\">\\((x,p)\\)</span> מוכל כולו בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>,</span> ושם כבר יש איבר של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\subseteq A\\cup B\\)</span>!</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:2.8,&quot;ymin&quot;:-0.6,&quot;ymax&quot;:0.6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;i0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;i1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1.5&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;j0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;j1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=2.5&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;px&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.5,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;x in I&quot;},{&quot;id&quot;:&quot;pp&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1.2,0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;p in I cap J&quot;},{&quot;id&quot;:&quot;py&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(2.1,0)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;y in J&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איך מטפלים ב-$x\\in I\\setminus J$ ו-$y\\in J\\setminus I$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איך מטפלים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\in I\\setminus J\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\in J\\setminus I\\)</span></span></p><div class=\"callout-body\"><p>סמנו <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(p\\in I\\cap J\\)</span></span> נקודה משותפת לשני הקטעים. הראו שאם <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in I\\setminus J\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\in J\\setminus I\\)</span></span> (עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>),</span> אז בהכרח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;p&lt;y\\)</span>!</span> למה זה פותר מיד את טענה 1?</p></div></div>"},{"title":"רמז 2: דוגמה נגדית פשוטה לטענה 2","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: דוגמה נגדית פשוטה לטענה 2</p><div class=\"callout-body\"><p>מה אם <span class=\"math math-inline\" dir=\"ltr\">\\(I=J=\\mathbb R\\)</span> (אכן יש נקודה משותפת!), <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוכיח את טענה 1 על ידי הפרדת מקרים לזוג <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\cup J\\)</span>:</span></span> אם שניהם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> או שניהם <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span>,</span></span> הצפיפות מיד נותנת איבר <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span>;</span></span> אם אחד <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\setminus J\\)</span></span> והשני <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\setminus I\\)</span>,</span></span> הנקודה המשותפת <span class=\"math math-inline\" dir=\"ltr\">\\(p\\in I\\cap J\\)</span> שוכנת בהכרח ביניהם ולכן מפצלת לתת-פתח בתוך <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> (או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span>).</span> נפריך את טענה 2 עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=J=\\mathbb R\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: נכונה.</strong> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\cup J\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\)</span>,</span> אז מצפיפות <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\subseteq A\\cup B\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span></span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in J\\)</span>,</span> אז מצפיפות <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(b\\in B\\subseteq A\\cup B\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;b&lt;y\\)</span>.</span></span></li><li>נניח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\in I\\setminus J\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\in J\\setminus I\\)</span>.</span></span> תהי <span class=\"math math-inline\" dir=\"ltr\">\\(p\\in I\\cap J\\)</span> נקודה משותפת לשני הקטעים. נבדוק את מיקומה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span>:</span> לכן בהכרח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;p&lt;y\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x,p\\in I\\)</span></span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p\\in I\\cap J\\subseteq I\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\subseteq A\\cup B\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;p&lt;y\\)</span>,</span></span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span><ul><li>לא ייתכן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p\\le x\\)</span>,</span></span> כי אז <span class=\"math math-inline\" dir=\"ltr\">\\(p&lt;x&lt;y\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p,y\\in J\\)</span>,</span> ומכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span></span> קטע נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in J\\)</span>,</span> בסתירה לכך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\notin J\\)</span>.</span></span></li><li>לא ייתכן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\le p\\)</span>,</span></span> כי אז <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y&lt;p\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,p\\in I\\)</span>,</span> ומכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> קטע נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\in I\\)</span>,</span> בסתירה לכך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\notin I\\)</span>.</span></span></li></ul></li><li>במקרה הסימטרי <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in J\\setminus I\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\in I\\setminus J\\)</span>,</span></span> באותו שיקול בדיוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;p&lt;y\\)</span>,</span> ובקטע <span class=\"math math-inline\" dir=\"ltr\">\\((x,p)\\subseteq J\\)</span> יש איבר <span class=\"math math-inline\" dir=\"ltr\">\\(b\\in B\\subseteq A\\cup B\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;b&lt;p&lt;y\\)</span>.</span></li></ul>\n<p><em>למה?</em> תכונת הקטע אינה מאפשרת לקצוות של <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> ושל <span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span> &quot;לדלג&quot; זה מעל זה בלי להכיל את נקודת החיבור <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> ביניהם, וכך <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> תמיד פורסת תת-קטע שנמצא לגמרי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> או <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span>.</span></span></p>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\cup J\\)</span>.</span></span></p>\n<p><strong>טענה 2: לא נכונה.</strong> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(I=J=\\mathbb R\\)</span> (יש אינסוף נקודות משותפות, והאיחוד הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>),</span> <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> (צפופה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> לפי משפט 1.66) <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span></span> (שגם היא צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> כפי שהוכח באמצעות הוספת <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{2}\\)</span> לצפיפות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb Q\\)</span>).</span></p>\n<p>אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B=\\mathbb Q\\cap(\\mathbb R\\setminus\\mathbb Q)=\\emptyset\\)</span>,</span> והקבוצה הריקה אינה צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: טענה 1 בלבד נכונה (תשובה <strong>א</strong>).</p></div></div>","steps":["<p><strong>טענה 1: נכונה.</strong> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\cup J\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\)</span>,</span> אז מצפיפות <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\subseteq A\\cup B\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span></span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in J\\)</span>,</span> אז מצפיפות <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(b\\in B\\subseteq A\\cup B\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;b&lt;y\\)</span>.</span></span></li><li>נניח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\in I\\setminus J\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\in J\\setminus I\\)</span>.</span></span> תהי <span class=\"math math-inline\" dir=\"ltr\">\\(p\\in I\\cap J\\)</span> נקודה משותפת לשני הקטעים. נבדוק את מיקומה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span>:</span> לכן בהכרח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;p&lt;y\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x,p\\in I\\)</span></span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p\\in I\\cap J\\subseteq I\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\subseteq A\\cup B\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;p&lt;y\\)</span>,</span></span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span><ul><li>לא ייתכן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p\\le x\\)</span>,</span></span> כי אז <span class=\"math math-inline\" dir=\"ltr\">\\(p&lt;x&lt;y\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p,y\\in J\\)</span>,</span> ומכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span></span> קטע נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in J\\)</span>,</span> בסתירה לכך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\notin J\\)</span>.</span></span></li><li>לא ייתכן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\le p\\)</span>,</span></span> כי אז <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y&lt;p\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,p\\in I\\)</span>,</span> ומכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> קטע נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\in I\\)</span>,</span> בסתירה לכך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\notin I\\)</span>.</span></span></li></ul></li><li>במקרה הסימטרי <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in J\\setminus I\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\in I\\setminus J\\)</span>,</span></span> באותו שיקול בדיוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;p&lt;y\\)</span>,</span> ובקטע <span class=\"math math-inline\" dir=\"ltr\">\\((x,p)\\subseteq J\\)</span> יש איבר <span class=\"math math-inline\" dir=\"ltr\">\\(b\\in B\\subseteq A\\cup B\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;b&lt;p&lt;y\\)</span>.</span></li></ul>\n<p><em>למה?</em> תכונת הקטע אינה מאפשרת לקצוות של <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> ושל <span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span> &quot;לדלג&quot; זה מעל זה בלי להכיל את נקודת החיבור <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> ביניהם, וכך <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> תמיד פורסת תת-קטע שנמצא לגמרי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> או <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span>.</span></span></p>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\cup J\\)</span>.</span></span></p>","<p><strong>טענה 2: לא נכונה.</strong> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(I=J=\\mathbb R\\)</span> (יש אינסוף נקודות משותפות, והאיחוד הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>),</span> <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> (צפופה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> לפי משפט 1.66) <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span></span> (שגם היא צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> כפי שהוכח באמצעות הוספת <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{2}\\)</span> לצפיפות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb Q\\)</span>).</span></p>\n<p>אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B=\\mathbb Q\\cap(\\mathbb R\\setminus\\mathbb Q)=\\emptyset\\)</span>,</span> והקבוצה הריקה אינה צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: טענה 1 בלבד נכונה (תשובה <strong>א</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>בטענה 1, לשכוח את המקרה המעורב שבו <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> נמצא רק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span></span> נמצא רק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(J\\)</span>,</span></span> ולהניח סתם כך ששתי הנקודות יחד באותו קטע.</li><li>לדמיין את טענה 1 רק על <span class=\"math math-inline\" dir=\"ltr\">\\(I=[0,1], J=(1,2]\\)</span> ולחשוב &quot;הנה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> החיתוך ריק&quot; — הנתון אומר מפורשות שיש נקודה משותפת!</li></ul></div></div>"}],"similar":"","mc":{"1":true,"2":false}},"7":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><ol><li>קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> המוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> ורציפה בנקודה אחת בדיוק.</li><li>קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> המוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> ואינה רציפה בנקודה אחת בדיוק (כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בכל נקודה פרט לנקודה אחת בדיוק בה אינה רציפה).</li><li>קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> המוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> וגזירה בנקודה אחת בדיוק.</li><li>קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> המוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> ואינה גזירה בנקודה אחת בדיוק (כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל נקודה פרט לנקודה אחת בדיוק בה אינה גזירה).</li></ol>\n<p>הטענות הנכונות הן: א. 1,2 ב. 3,4 ג. 1,3 ד. 2,4 ה. 1,2,3 ו. 1,2,4 ז. 1,2,3,4 ח. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כל ארבע האפשרויות קיימות בפועל — אפשר שפונקציה תהיה רציפה או גזירה בדיוק בנקודה אחת (בעזרת מלקחיים שמחבקים את דיריכלה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span></span> ואפשר שתתקלקל בדיוק בנקודה אחת (בעזרת קפיצה בודדת או שפיץ בודד כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\)</span>).</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כל ארבע האפשרויות קיימות בפועל — אפשר שפונקציה תהיה רציפה או גזירה בדיוק בנקודה אחת (בעזרת מלקחיים שמחבקים את דיריכלה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span></span> ואפשר שתתקלקל בדיוק בנקודה אחת (בעזרת קפיצה בודדת או שפיץ בודד כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\)</span>).</span></p>\n<p><strong>תמונה בראש</strong>: בטענה 1, לוקחים את פונקציית דיריכלה הקופצנית (שקופצת בכל מקום בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>)</span></span> ולוחצים אותה בתוך מלקחיים בצורת <span class=\"math math-inline\" dir=\"ltr\">\\(X\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span>):</span></span> רק בצומת <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> המלקחיים סוגרים אותה לגובה אחד ולכן רק שם היא רציפה! בטענה 3, משתמשים במלקחיים בצורת פרבולה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(y=x^2\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span>):</span></span> שם הנגזרת של שני הזרועות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> ולכן גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> יש גזירות — ורק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!</span></span> בטענות 2 ו-4, זה פשוט כביש חלק לגמרי שיש בו בור אחד (טענה 2) או פינה חדה אחת כמו הערך המוחלט <span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\)</span> (טענה 4).</p>\n<p><strong>עם מספרים</strong>: בטענה 3, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}x^2 &amp; x\\in\\mathbb Q\\\\0 &amp; x\\notin\\mathbb Q\\end{cases}\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0.01\\)</span></span> יש נקודות קרובות מאוד (רציונליות ואי-רציונליות) עם ערכים <span class=\"math math-inline\" dir=\"ltr\">\\(0.0001\\)</span> מול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> ולכן אין גבול שם; אבל ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span> היחס <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)-0}{x}\\)</span> הוא בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> ולכן שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!</span></span></p>\n<p><strong>אי-רציפות בנקודה</strong> או <strong>אי-גזירות בנקודה</strong> אינן דורשות קלקול בסביבה שלמה — מספיק לקלקל בנקודה בודדת כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף (טענות 1 ו-3)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (טענות 1 ו-3)</span></summary><div class=\"callout-body\"><p>המלקחיים של טענה 1 (הקווים האדומים המקווקווים <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span>)</span></span> ושל טענה 3 (הפרבולה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(y=x^2\\)</span> וציר <span class=\"nobr\">ה-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>):</span></span> הנקודה הירוקה <span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span> היא המקום היחיד שבו שתי ה&quot;שכבות&quot; (רציונליים ואי-רציונליים) נמעכות יחד לאותו ערך (ובפרבולה — אפילו עם אותו שיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)!</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-2,&quot;xmax&quot;:2,&quot;ymin&quot;:-1.5,&quot;ymax&quot;:2.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;p&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x^2&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;z&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0&quot;,&quot;color&quot;:&quot;#666666&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"},{"title":"רואים את זה בגרף (טענה 4)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (טענה 4)</span></summary><div class=\"callout-body\"><p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=|x|\\)</span> מדגימה את טענה 4: היא גזירה וחלקה בכל נקודה מימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (שיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(+1\\)</span>)</span> ובכל נקודה משמאל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (שיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>),</span> ואינה גזירה <strong>רק</strong> בשפיץ החד שבאפס <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-2.5,&quot;xmax&quot;:2.5,&quot;ymin&quot;:-0.4,&quot;ymax&quot;:2.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=|x|&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מתאימים דוגמה מפורשת לכל טענה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מתאימים דוגמה מפורשת לכל טענה</p><div class=\"callout-body\"><p>לכל אחת מ-4 הטענות (&quot;קיימת פונקציה...&quot;), מספיק לבנות דוגמה אחת קונקרטית על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> לאילו פונקציות מסוג דיריכלה יש רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בלבד או גזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בלבד?</p></div></div>"},{"title":"רמז 2: דוגמאות לטענות 2 ו-4","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: דוגמאות לטענות 2 ו-4</p><div class=\"callout-body\"><p>טענה 2: קחו פונקציה שקופצת רק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (כמו <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> באפס <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בכל שאר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>).</span> טענה 4: איזו פונקציה מפורסמת רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ואינה גזירה בדיוק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נבנה דוגמה מפורשת לכל אחת מארבע הטענות: (1) <span class=\"math math-inline\" dir=\"ltr\">\\(x\\cdot D(x)\\)</span> רציפה רק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> (2) פונקציית אינדיקטור של <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0\\}\\)</span> לא רציפה רק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> (3) <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\cdot D(x)\\)</span> גזירה רק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> (4) <span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\)</span> אינה גזירה רק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> לכן כל ארבע הטענות נכונות.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: נכונה.</strong> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}x &amp; x\\in\\mathbb Q\\\\ 0 &amp; x\\notin\\mathbb Q\\end{cases}\\)</span>.</span></p>\n<ul><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span></em>: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le |f(x)-f(0)|=|f(x)|\\le |x|\\)</span>,</span> וממשפט הסנדוויץ׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0=f(0)\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span></span></em>: לפי צפיפות הרציונליים והאי-רציונליים (משפט 1.66), קיימת סדרת רציונליים <span class=\"math math-inline\" dir=\"ltr\">\\(q_n\\to x_0\\)</span> וסדרת אי-רציונליים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r_n\\to x_0\\)</span>.</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f(q_n)=q_n\\to x_0\\ne 0\\)</span> בעוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(r_n)=0\\to 0\\)</span>.</span> לפי היינה, אין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>,</span></span> ולכן היא אינה רציפה שם.</li></ul>\n<p><strong>טענה 2: נכונה.</strong> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}1 &amp; x=0\\\\ 0 &amp; x\\ne 0\\end{cases}\\)</span>.</span></p>\n<ul><li>בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>,</span> הפונקציה זהה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בסביבה קטנה של <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span> (למשל <span class=\"math math-inline\" dir=\"ltr\">\\((x_0-|x_0|/2, x_0+|x_0|/2)\\)</span> שאינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span> ולכן רציפה שם.</li><li><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0\\ne 1=f(0)\\)</span>,</span> ולכן אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li></ul>\n<p><strong>טענה 3: נכונה.</strong> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}x^2 &amp; x\\in\\mathbb Q\\\\ 0 &amp; x\\notin\\mathbb Q\\end{cases}\\)</span>.</span></p>\n<ul><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span></em>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>.</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> מנת ההפרשים מקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le\\left|\\frac{f(x)-f(0)}{x-0}\\right|=\\left|\\frac{f(x)}{x}\\right|\\le |x|\\)</span>.</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\to 0\\)</span>,</span> וממשפט הסנדוויץ׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}=0\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span></span></em>: לפי אותן סדרות <span class=\"math math-inline\" dir=\"ltr\">\\(q_n\\to x_0\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f(q_n)=q_n^2\\to x_0^2\\ne 0\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(r_n\\to x_0\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f(r_n)=0\\to 0\\)</span>),</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>,</span></span> ומכיוון שגזירות גוררת רציפות (משפט 7.9), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>.</span></span></li></ul>\n<p><em>למה?</em> הכפל של דיריכלה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> סוגר את הגובה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (נותן רציפות), אבל בחלוקה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> נשאר <span class=\"math math-inline\" dir=\"ltr\">\\(\\pm 1\\)</span> ולא מתכנס; הכפל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> משאיר אחרי חלוקה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> עדיין גורם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span> וזה נותן גזירות ממש!</p>\n<p><strong>טענה 4: נכונה.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=|x|\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> (גזירה, נגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-x\\)</span> (גזירה, נגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>),</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הנגזרות החד-צדדיות שונות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'_+(0)=1\\ne -1=f'_-(0)\\)</span>),</span> ולכן היא אינה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בלבד.</p>\n<p><strong>התשובה במבחן</strong>: כל ארבע הטענות (1,2,3,4) נכונות (תשובה <strong>ז</strong>).</p></div></div>","steps":["<p><strong>טענה 1: נכונה.</strong> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}x &amp; x\\in\\mathbb Q\\\\ 0 &amp; x\\notin\\mathbb Q\\end{cases}\\)</span>.</span></p>\n<ul><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span></em>: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le |f(x)-f(0)|=|f(x)|\\le |x|\\)</span>,</span> וממשפט הסנדוויץ׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0=f(0)\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span></span></em>: לפי צפיפות הרציונליים והאי-רציונליים (משפט 1.66), קיימת סדרת רציונליים <span class=\"math math-inline\" dir=\"ltr\">\\(q_n\\to x_0\\)</span> וסדרת אי-רציונליים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r_n\\to x_0\\)</span>.</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f(q_n)=q_n\\to x_0\\ne 0\\)</span> בעוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(r_n)=0\\to 0\\)</span>.</span> לפי היינה, אין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>,</span></span> ולכן היא אינה רציפה שם.</li></ul>","<p><strong>טענה 2: נכונה.</strong> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}1 &amp; x=0\\\\ 0 &amp; x\\ne 0\\end{cases}\\)</span>.</span></p>\n<ul><li>בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>,</span> הפונקציה זהה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בסביבה קטנה של <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span> (למשל <span class=\"math math-inline\" dir=\"ltr\">\\((x_0-|x_0|/2, x_0+|x_0|/2)\\)</span> שאינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span> ולכן רציפה שם.</li><li><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0\\ne 1=f(0)\\)</span>,</span> ולכן אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li></ul>","<p><strong>טענה 3: נכונה.</strong> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}x^2 &amp; x\\in\\mathbb Q\\\\ 0 &amp; x\\notin\\mathbb Q\\end{cases}\\)</span>.</span></p>\n<ul><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span></em>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>.</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> מנת ההפרשים מקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le\\left|\\frac{f(x)-f(0)}{x-0}\\right|=\\left|\\frac{f(x)}{x}\\right|\\le |x|\\)</span>.</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\to 0\\)</span>,</span> וממשפט הסנדוויץ׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}=0\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li><em><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span></span></em>: לפי אותן סדרות <span class=\"math math-inline\" dir=\"ltr\">\\(q_n\\to x_0\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f(q_n)=q_n^2\\to x_0^2\\ne 0\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(r_n\\to x_0\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f(r_n)=0\\to 0\\)</span>),</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>,</span></span> ומכיוון שגזירות גוררת רציפות (משפט 7.9), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>.</span></span></li></ul>\n<p><em>למה?</em> הכפל של דיריכלה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> סוגר את הגובה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (נותן רציפות), אבל בחלוקה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> נשאר <span class=\"math math-inline\" dir=\"ltr\">\\(\\pm 1\\)</span> ולא מתכנס; הכפל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> משאיר אחרי חלוקה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> עדיין גורם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span> וזה נותן גזירות ממש!</p>","<p><strong>טענה 4: נכונה.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=|x|\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> (גזירה, נגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-x\\)</span> (גזירה, נגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>),</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הנגזרות החד-צדדיות שונות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'_+(0)=1\\ne -1=f'_-(0)\\)</span>),</span> ולכן היא אינה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בלבד.</p>\n<p><strong>התשובה במבחן</strong>: כל ארבע הטענות (1,2,3,4) נכונות (תשובה <strong>ז</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>בטענה 3, לחשוב ש-&quot;אי אפשר להיות גזירה רק בנקודה אחת, כי גזירות בנקודה דורשת רציפות בסביבה שלה&quot;: זו טעות נפוצה! גזירות בנקודה דורשת רק שהפונקציה תהיה <strong>מוגדרת</strong> בסביבה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>,</span> והיא גוררת רציפות <strong>באותה נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span> בלבד</strong> (משפט 7.9), לא בסביבה שלמה!</li></ul></div></div>"}],"similar":"","mc":{"1":true,"2":true,"3":true,"4":true}},"8":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}(\\cos x)^{\\cot x} &amp; x&gt;0 \\\\ 1 &amp; x=0 \\\\ 4^{\\frac{a}{x}}+x^4\\cos\\left(\\frac{a}{x}\\right) &amp; x&lt;0.\\end{cases}\\]</div>\n<p>א. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> ב. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> ג. אף אחת מהטענות הנ&quot;ל אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">שני הצדדים צריכים לפגוש את הערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span>:</span> מצד ימין <span class=\"math math-inline\" dir=\"ltr\">\\((\\cos x)^{\\cot x}\\)</span> אכן שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ומצד שמאל כשמציבים <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(4^0+x^4=1+x^4\\)</span> שגם הוא שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>!</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: שני הצדדים צריכים לפגוש את הערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span>:</span> מצד ימין <span class=\"math math-inline\" dir=\"ltr\">\\((\\cos x)^{\\cot x}\\)</span> אכן שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ומצד שמאל כשמציבים <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(4^0+x^4=1+x^4\\)</span> שגם הוא שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>!</span></span></p>\n<p><strong>תמונה בראש</strong>: נמלה אחת מגיעה מימין ומזדחלת אל גובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> משמאל <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>)</span> מחכים לראות אם <span class=\"math math-inline\" dir=\"ltr\">\\(4^{a/x}\\)</span> יקפוץ למעלה או ייפול <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span></span> אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span> אז בגלל שגם <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> שני המינוסים מתבטלים והמנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> נהיית חיובית ענקית — אז <span class=\"math math-inline\" dir=\"ltr\">\\(4^{a/x}\\)</span> מתפוצץ לאינסוף! אבל אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> המעריך הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בדיוק עוד לפני שמתקרבים לאפס, כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(4^0=1\\)</span></span> והנמלה משמאל הולכת על הקו <span class=\"math math-inline\" dir=\"ltr\">\\(1+x^4\\)</span> ישר לתחנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: מימין <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.1\\)</span>:</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos(0.1)\\approx 0.995\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cot(0.1)\\approx 9.967\\)</span>,</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(0.995^{9.967}\\approx 0.951\\)</span></span> — <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0.01\\)</span></span> כבר יוצא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\approx 0.995\\to 1\\)</span>.</span> משמאל עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=-0.1\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4^0+(-0.1)^4\\cos(0)=1.0001\\to 1\\)</span>.</span></p>\n<p><strong>רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span></strong> דורשת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=\\lim_{x\\to 0^-}f(x)=f(0)\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>העקומה הכחולה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>)</span> מגיעה חלק אל הנקודה הירוקה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span> העקומה האדומה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>)</span> פוגשת אותה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> בדיוק <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span></span> (בצורת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+x^4\\)</span>).</span> הזיזו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>:</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span> העקומה האדומה עפה לאינסוף, ואם <span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span> היא נופלת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-1.2,&quot;xmax&quot;:1.3,&quot;ymin&quot;:-0.1,&quot;ymax&quot;:2.4}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;a&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;a=0&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:-0.5,&quot;max&quot;:0.5,&quot;step&quot;:0.25}},{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;r(x)=(\\\\cos(x))^{\\\\cot(x)}+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;l(x)=4^{\\\\frac{a}{x}}+x^4\\\\cdot\\\\cos\\\\left(\\\\frac{a}{x}\\\\right)+0\\\\cdot\\\\sqrt{-x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,1)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: חישוב הגבול מימין $\\lim_{x\\to 0^+}(\\cos x)^{\\cot x}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: חישוב הגבול מימין <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}(\\cos x)^{\\cot x}\\)</span></p><div class=\"callout-body\"><p>כתבו <span class=\"math math-inline\" dir=\"ltr\">\\((\\cos x)^{\\cot x}=e^{\\cot x\\cdot\\ln(\\cos x)}\\)</span> (<span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\frac{\\pi}{2})\\)</span></span> שבו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x&gt;0\\)</span>)</span> וחשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}\\frac{\\ln(\\cos x)}{\\tan x}\\)</span> בעזרת כלל לופיטל (משפט 8.13).</p></div></div>"},{"title":"רמז 2: הצבת $a=0$ בענף של $x<0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: הצבת <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> בענף של <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span></p><div class=\"callout-body\"><p>שימו לב: עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> ולכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>,</span> השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0}{x}\\)</span> שווה ממש <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>).</span></span> למה שווה הביטוי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נחשב את הגבול מימין על ידי הצגת <span class=\"math math-inline\" dir=\"ltr\">\\((\\cos x)^{\\cot x}=e^{\\frac{\\ln(\\cos x)}{\\tan x}}\\)</span> ומציאת גבול המעריך בעזרת לופיטל: מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^0=1=f(0)\\)</span>.</span> כעת נבדוק משמאל: עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> הענף השמאלי מתפשט <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1+x^4\\to 1=f(0)\\)</span></span> ולכן הפונקציה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span> היחס <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\to+\\infty\\)</span> ולכן הגבול משמאל הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: חישוב הגבול מימין <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>).</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\left(0,\\frac{\\pi}{2}\\right)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x&gt;0\\)</span>,</span> ולכן ניתן לכתוב:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(\\cos x)^{\\cot x}=e^{\\cot x\\cdot\\ln(\\cos x)}=e^{\\frac{\\ln(\\cos x)}{\\tan x}}.\\]</div>\n<p>נחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}\\frac{\\ln(\\cos x)}{\\tan x}\\)</span> באמצעות כלל לופיטל (משפט 8.13 בגרסה החד-צדדית): המונה והמכנה גזירים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left(0,\\frac{\\pi}{2}\\right)\\)</span>,</span></span> שניהם שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 1=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan 0=0\\)</span>),</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\tan x)'=\\frac{1}{\\cos^2 x}\\ne 0\\)</span>.</span></span> נגזור מונה ומכנה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{(\\ln(\\cos x))'}{(\\tan x)'}=\\lim_{x\\to 0^+}\\frac{\\frac{-\\sin x}{\\cos x}}{\\frac{1}{\\cos^2 x}}=\\lim_{x\\to 0^+}(-\\sin x\\cos x)=0.\\]</div>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}\\frac{\\ln(\\cos x)}{\\tan x}=0\\)</span>,</span></span> ומרציפות הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}f(x)=e^0=1=f(0).\\]</div>\n<p><strong>שלב 2: בדיקת אפשרות א <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>).</span></strong> נציב <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> בענף של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>:</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0}{x}=0\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=4^0+x^4\\cos(0)=1+x^4.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}(1+x^4)=1+0=1=f(0)=\\lim_{x\\to 0^+}f(x)\\)</span>.</span></p>\n<p><em>למה?</em> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> קבוע ולא משתנה, השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> אינו מצורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac00\\)</span> אלא שווה ממש לאפס לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(4^0=1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos 0=1\\)</span>.</span></span></p>\n<p>מכאן שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ואפשרות א נכונה.</p>\n<p><strong>שלב 3: מדוע אפשרות ב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>)</span> נפסלת (לביטחון).</strong> אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span> אז עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}&gt;0\\)</span></span> ושואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span>.</span></span> לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4^{\\frac{a}{x}}\\to+\\infty\\)</span>,</span> בעוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x^4\\cos(\\frac{a}{x})|\\le x^4\\to 0\\)</span>.</span> מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}f(x)=\\infty\\ne 1\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (תשובה <strong>א</strong>).</p></div></div>","steps":["<p><strong>שלב 1: חישוב הגבול מימין <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>).</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\left(0,\\frac{\\pi}{2}\\right)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x&gt;0\\)</span>,</span> ולכן ניתן לכתוב:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(\\cos x)^{\\cot x}=e^{\\cot x\\cdot\\ln(\\cos x)}=e^{\\frac{\\ln(\\cos x)}{\\tan x}}.\\]</div>\n<p>נחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}\\frac{\\ln(\\cos x)}{\\tan x}\\)</span> באמצעות כלל לופיטל (משפט 8.13 בגרסה החד-צדדית): המונה והמכנה גזירים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left(0,\\frac{\\pi}{2}\\right)\\)</span>,</span></span> שניהם שואפים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 1=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan 0=0\\)</span>),</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\tan x)'=\\frac{1}{\\cos^2 x}\\ne 0\\)</span>.</span></span> נגזור מונה ומכנה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{(\\ln(\\cos x))'}{(\\tan x)'}=\\lim_{x\\to 0^+}\\frac{\\frac{-\\sin x}{\\cos x}}{\\frac{1}{\\cos^2 x}}=\\lim_{x\\to 0^+}(-\\sin x\\cos x)=0.\\]</div>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}\\frac{\\ln(\\cos x)}{\\tan x}=0\\)</span>,</span></span> ומרציפות הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}f(x)=e^0=1=f(0).\\]</div>","<p><strong>שלב 2: בדיקת אפשרות א <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>).</span></strong> נציב <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> בענף של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>:</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0}{x}=0\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=4^0+x^4\\cos(0)=1+x^4.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}(1+x^4)=1+0=1=f(0)=\\lim_{x\\to 0^+}f(x)\\)</span>.</span></p>\n<p><em>למה?</em> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> קבוע ולא משתנה, השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> אינו מצורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac00\\)</span> אלא שווה ממש לאפס לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(4^0=1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos 0=1\\)</span>.</span></span></p>\n<p>מכאן שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ואפשרות א נכונה.</p>","<p><strong>שלב 3: מדוע אפשרות ב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>)</span> נפסלת (לביטחון).</strong> אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span> אז עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}&gt;0\\)</span></span> ושואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span>.</span></span> לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4^{\\frac{a}{x}}\\to+\\infty\\)</span>,</span> בעוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x^4\\cos(\\frac{a}{x})|\\le x^4\\to 0\\)</span>.</span> מכאן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}f(x)=\\infty\\ne 1\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (תשובה <strong>א</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(4^{a/x}\\)</span> הוא &quot;צורת אי-ודאות <span class=\"math math-inline\" dir=\"ltr\">\\(4^{0/0}\\)</span>&quot;: השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0}{x}\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> הוא המספר <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ממש!</li><li>לטעות בסימן בענף <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>:</span></span> שני מספרים שליליים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>)</span></span> נותנים יחס חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\to+\\infty\\)</span>,</span> לא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":{"answer":"א"}},"9":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><ol><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;b&lt;\\frac{\\pi}{2}\\)</span> מתקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\ln(\\cot b)-\\ln(\\cot a)|&lt;|b-a|\\)</span>.</span></li><li>קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}\\left(f(x)+\\left(e^{x^2}+\\cos x\\right)\\right)=2\\)</span>.</span></span></li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 1,2 ד. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בטענה 1 הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln(\\cot x)\\)</span> צונחת הרבה יותר מהר משיפוע <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> (הפרש הערכים תמיד גדול לפחות פי <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> מהמרחק על ציר <span class=\"nobr\">ה-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>),</span></span> ובטענה 2 האיבר <span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span> עף לאינסוף ושום פונקציה חסומה לא יכולה לבטל אותו כדי להגיע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בטענה 1 הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln(\\cot x)\\)</span> צונחת הרבה יותר מהר משיפוע <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> (הפרש הערכים תמיד גדול לפחות פי <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> מהמרחק על ציר <span class=\"nobr\">ה-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>),</span></span> ובטענה 2 האיבר <span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span> עף לאינסוף ושום פונקציה חסומה לא יכולה לבטל אותו כדי להגיע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: בטענה 1, תדמיינו מגלשה תלולה במיוחד ששיפועה בערך מוחלט תמיד לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>:</span> על כל מטר של התקדמות ימינה יורדים לפחות שני מטרים למטה, ולכן השינוי האנכי לעולם אינו קטן מהמרחק האופקי. בטענה 2, יש בלון הליום ענק <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span>)</span> שעולה לחלל בעוצמה שהולכת וגדלה בלי סוף; אם ננסה למשוך אותו למטה רק עם משקולת מוגבלת בגודלה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חסומה), הוא עדיין יטוס לשמיים ולא יישאר בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>!</span></p>\n<p><strong>עם מספרים</strong>: בטענה 1, נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(a=\\frac{\\pi}{6}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\frac{\\pi}{3}\\)</span>:</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\cot\\frac{\\pi}{6}=\\sqrt{3}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cot\\frac{\\pi}{3}=\\frac{1}{\\sqrt{3}}\\)</span>,</span></span> ולכן ההפרש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 3&gt;1\\)</span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3&gt;e\\)</span>),</span> בעוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b-a|=\\frac{\\pi}{6}&lt;1\\)</span>!</span> בטענה 2, אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> אז <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=10\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{100}+\\cos 10 + f(10)\\ge e^{100}-1-M\\to\\infty\\)</span>.</span></p>\n<p><strong>פונקציה חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span></strong> אינה יכולה להקטין ביטוי ששואף לאינסוף, כי אפשר לחסור ממנו רק עד קבוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף (טענה 1)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (טענה 1)</span></summary><div class=\"callout-body\"><p>הגרף הכחול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\ln(\\cot x)\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac{\\pi}{2})\\)</span>,</span> והנקודות הירוקות הן <span class=\"math math-inline\" dir=\"ltr\">\\(a=\\frac{\\pi}{6}\\approx 0.524\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\frac{\\pi}{3}\\approx 1.047\\)</span>.</span></span> משוואת הירידה מהירה יותר מהקו האדום המקווקו <span class=\"math math-inline\" dir=\"ltr\">\\(y=-x\\)</span> ששיפועו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\ln(\\cot b)-\\ln(\\cot a)|=\\ln 3&gt;1&gt;|b-a|=\\frac{\\pi}{6}\\)</span>!</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0,&quot;xmax&quot;:1.65,&quot;ymin&quot;:-2.2,&quot;ymax&quot;:2.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\ln(\\\\cot(x))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=-x&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.5236,g(0.5236))&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;x=pi/6&quot;},{&quot;id&quot;:&quot;pb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1.0472,g(1.0472))&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;x=pi/3&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"},{"title":"רואים את זה בגרף (טענה 2)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (טענה 2)</span></summary><div class=\"callout-body\"><p>העקומה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}+\\cos x\\)</span> מזנקת במהירות אדירה לאינסוף. גם אם נחסיר ממנה משקולת חסומה (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-10\\)</span>,</span> העקומה האדומה המקווקוות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}+\\cos x-10\\)</span>),</span> היא עדיין עוברת בהרבה את קו הגובה <span class=\"math math-inline\" dir=\"ltr\">\\(y=2\\)</span> וממשיכה לאינסוף.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:2.5,&quot;ymin&quot;:-2,&quot;ymax&quot;:30}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=e^{x^2}+\\\\cos(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;s&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=g(x)-10&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: נגזרת של $\\ln(\\cot x)$ או זוויות מוכרות בטענה 1","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: נגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln(\\cot x)\\)</span> או זוויות מוכרות בטענה 1</p><div class=\"callout-body\"><p>חשבו את הנגזרת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln(\\cot x)\\)</span>:</span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac{1}{\\sin x\\cos x}=-\\frac{2}{\\sin(2x)}\\)</span>,</span> שגודלו תמיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ge 2\\)</span>!</span> או הציבו ישר <span class=\"math math-inline\" dir=\"ltr\">\\(a=\\frac{\\pi}{6}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\frac{\\pi}{3}\\)</span>.</span></span></p></div></div>"},{"title":"רמז 2: שימו לב לסימן שבמעריך ב-2","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימו לב לסימן שבמעריך ב-2</p><div class=\"callout-body\"><p>במעריך כתוב <span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span> (ולא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x^2}\\)</span>)!</span> לאן שואף <span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span>,</span></span> והאם פונקציה חסומה יכולה לבטל אותו?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפריך את טענה 1 בהצבת <span class=\"math math-inline\" dir=\"ltr\">\\(a=\\frac{\\pi}{6}, b=\\frac{\\pi}{3}\\)</span> (שם ההפרש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 3&gt;1\\)</span> ואילו המרחק בין הנקודות הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{6}&lt;1\\)</span>,</span> וגם נצביע על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|g'(x)|=\\frac{2}{\\sin(2x)}\\ge 2\\)</span>).</span> נפריך את טענה 2 על ידי הראה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> הביטוי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)+e^{x^2}+\\cos x\\ge e^{x^2}-M-1\\to\\infty\\)</span>,</span> בסתירה לגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: לא נכונה.</strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(a=\\frac{\\pi}{6}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\frac{\\pi}{3}\\)</span>,</span></span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{\\pi}{6}&lt;\\frac{\\pi}{3}&lt;\\frac{\\pi}{2}\\)</span>.</span> נחשב את שני האגפים:</p>\n<ul><li>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\cot\\left(\\frac{\\pi}{6}\\right)=\\sqrt{3}\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cot\\left(\\frac{\\pi}{3}\\right)=\\frac{1}{\\sqrt{3}}\\)</span>,</span></span> מתקיים:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\ln\\left(\\cot\\frac{\\pi}{3}\\right)-\\ln\\left(\\cot\\frac{\\pi}{6}\\right)\\right|=\\left|\\ln\\frac{1}{\\sqrt{3}}-\\ln\\sqrt{3}\\right|=\\left|-\\ln\\left(\\sqrt{3}\\cdot\\sqrt{3}\\right)\\right|=\\ln 3.\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e&lt;3\\)</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span> עולה ממש, מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 3&gt;\\ln e=1\\)</span>.</span></p>\n<ul><li>מאידך, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left|b-a\\right|=\\frac{\\pi}{3}-\\frac{\\pi}{6}=\\frac{\\pi}{6}&lt;\\frac{4}{6}&lt;1\\)</span>.</span></li></ul>\n<p>לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\ln(\\cot b)-\\ln(\\cot a)|=\\ln 3&gt;1&gt;|b-a|\\)</span>,</span> בסתירה לטענה. (ואכן, נגזרת הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\ln(\\cot x)\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=-\\frac{2}{\\sin(2x)}\\)</span>,</span> ולכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;b&lt;\\frac{\\pi}{2}\\)</span> מתקיים לפי לגראנז׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|g(b)-g(a)|=\\frac{2}{\\sin(2c)}|b-a|\\ge 2|b-a|&gt;|b-a|\\)</span>.)</span></p>\n<p><strong>טענה 2: לא נכונה.</strong> נניח לצורך הפרכה שקיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> כלומר קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\ge -M\\)</span>.</span></p>\n<p>בנוסף, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x\\ge -1\\)</span>.</span> לכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)+\\left(e^{x^2}+\\cos x\\right)\\ge e^{x^2}-M-1.\\]</div>\n<p><em>למה?</em> איבר חסום וקוסינוס יכולים להוריד את הערך הכולל לכל היותר בכמות קבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M+1\\)</span>,</span> בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span></span> עובר כל תקרה אפשרית.</p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}e^{x^2}=\\infty\\)</span>,</span></span> גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}(e^{x^2}-M-1)=\\infty\\)</span>,</span> ולכן לפי תכונות גבולות אינסופיים (או השוואה) מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}\\left(f(x)+\\left(e^{x^2}+\\cos x\\right)\\right)=\\infty\\ne 2.\\]</div>\n<p>לכן לא קיימת אף פונקציה חסומה המקיימת זאת.</p>\n<p><strong>התשובה במבחן</strong>: אף טענה אינה נכונה (תשובה <strong>ד</strong>).</p></div></div>","steps":["<p><strong>טענה 1: לא נכונה.</strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(a=\\frac{\\pi}{6}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\frac{\\pi}{3}\\)</span>,</span></span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{\\pi}{6}&lt;\\frac{\\pi}{3}&lt;\\frac{\\pi}{2}\\)</span>.</span> נחשב את שני האגפים:</p>\n<ul><li>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\cot\\left(\\frac{\\pi}{6}\\right)=\\sqrt{3}\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cot\\left(\\frac{\\pi}{3}\\right)=\\frac{1}{\\sqrt{3}}\\)</span>,</span></span> מתקיים:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\ln\\left(\\cot\\frac{\\pi}{3}\\right)-\\ln\\left(\\cot\\frac{\\pi}{6}\\right)\\right|=\\left|\\ln\\frac{1}{\\sqrt{3}}-\\ln\\sqrt{3}\\right|=\\left|-\\ln\\left(\\sqrt{3}\\cdot\\sqrt{3}\\right)\\right|=\\ln 3.\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e&lt;3\\)</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln\\)</span> עולה ממש, מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\ln 3&gt;\\ln e=1\\)</span>.</span></p>\n<ul><li>מאידך, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left|b-a\\right|=\\frac{\\pi}{3}-\\frac{\\pi}{6}=\\frac{\\pi}{6}&lt;\\frac{4}{6}&lt;1\\)</span>.</span></li></ul>\n<p>לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\ln(\\cot b)-\\ln(\\cot a)|=\\ln 3&gt;1&gt;|b-a|\\)</span>,</span> בסתירה לטענה. (ואכן, נגזרת הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\ln(\\cot x)\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=-\\frac{2}{\\sin(2x)}\\)</span>,</span> ולכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;b&lt;\\frac{\\pi}{2}\\)</span> מתקיים לפי לגראנז׳ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|g(b)-g(a)|=\\frac{2}{\\sin(2c)}|b-a|\\ge 2|b-a|&gt;|b-a|\\)</span>.)</span></p>","<p><strong>טענה 2: לא נכונה.</strong> נניח לצורך הפרכה שקיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> כלומר קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\ge -M\\)</span>.</span></p>\n<p>בנוסף, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x\\ge -1\\)</span>.</span> לכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)+\\left(e^{x^2}+\\cos x\\right)\\ge e^{x^2}-M-1.\\]</div>\n<p><em>למה?</em> איבר חסום וקוסינוס יכולים להוריד את הערך הכולל לכל היותר בכמות קבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M+1\\)</span>,</span> בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span></span> עובר כל תקרה אפשרית.</p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}e^{x^2}=\\infty\\)</span>,</span></span> גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}(e^{x^2}-M-1)=\\infty\\)</span>,</span> ולכן לפי תכונות גבולות אינסופיים (או השוואה) מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}\\left(f(x)+\\left(e^{x^2}+\\cos x\\right)\\right)=\\infty\\ne 2.\\]</div>\n<p>לכן לא קיימת אף פונקציה חסומה המקיימת זאת.</p>\n<p><strong>התשובה במבחן</strong>: אף טענה אינה נכונה (תשובה <strong>ד</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>בטענה 2, לקרוא בטעות את <span class=\"math math-inline\" dir=\"ltr\">\\(e^{x^2}\\)</span> כאילו היה כתוב <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x^2}\\)</span> (כמו במועד 81), ולהאמין שאפשר לקחת <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=2-e^{x^2}-\\cos x\\)</span> בלי לשים לב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> זו בורחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span></span> ואינה חסומה.</li><li>בטענה 1, לחשוב שנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\ln x\\)</span> היא <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1x\\)</span> ושוכח להתחשב בכלל השרשרת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cot x\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":{"1":false,"2":false}},"10":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה המוגדרת בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>\n<ol><li>אם לכל קטע <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span>,</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></li><li>אם לכל קטע <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span>,</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 1,2 ד. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">ההתחייבות נתונה רק על תת-קטעים סגורים בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> שלא נוגעים בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>:</span></span> ליד הקצה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> הפונקציה יכולה עדיין לטפס לאינסוף (מפיל את 1) וגם יכולה לעשות קפיצה נקודתית ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> (מפיל את 2) — אפילו שהיא מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>!</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: ההתחייבות נתונה רק על תת-קטעים סגורים בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> שלא נוגעים בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>:</span></span> ליד הקצה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> הפונקציה יכולה עדיין לטפס לאינסוף (מפיל את 1) וגם יכולה לעשות קפיצה נקודתית ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> (מפיל את 2) — אפילו שהיא מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>!</span></span></p>\n<p><strong>תמונה בראש</strong>: זה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> רק מבטיח שבנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> רשום מספר כלשהו (נגיד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span> אבל המספר הזה לא מחייב את הפונקציה להיות רציפה לידו! בטענה 1, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> יכולה לתת את הערך <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span></span> ולימין <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> לנסוק לאינסוף כמו <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x-a}\\)</span> — כך שעל כל <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span> שמתרחק קצת <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> הכול חסום, ועדיין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> היא אינה חסומה. בטענה 2, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> יכולה להיות <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\((a,b]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span></span> ואז היא רציפה על כל <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span> אבל לא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> בגלל הקפיצה בקצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> קחו <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac1x\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,2)\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=f(2)=0\\)</span>.</span></span> היא מוגדרת בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> חסומה על <span class=\"math math-inline\" dir=\"ltr\">\\([0.1,1.9]\\)</span> (עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span>),</span> על <span class=\"math math-inline\" dir=\"ltr\">\\([0.01,1.99]\\)</span> (עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(100\\)</span>),</span> אבל לא חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span>.</span></span> ובטענה 2, <span class=\"math math-inline\" dir=\"ltr\">\\(g(0)=1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=0\\)</span></span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,2]\\)</span></span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(0,2)\\)</span> אבל קופצת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>קיום הגדרה בקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></strong> אין פירושו רציפות בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> — הערך בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> יכול להיקבע בנפרד מהערכים שבתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac1x\\)</span> בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span>,</span> והנקודה האדומה <span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span> מראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מוגדרת גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>).</span> הזיזו את הקצה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> של תת-הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([c,1.5]\\)</span> (בין הקווים הירוק והאדום): בכל קטע <span class=\"math math-inline\" dir=\"ltr\">\\([c,1.5]\\)</span> הפונקציה חסומה עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1c\\)</span>,</span> אבל ככל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\to 0^+\\)</span></span> הגבהים בורחים לאינסוף בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span>!</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:2.3,&quot;ymin&quot;:-1.5,&quot;ymax&quot;:22}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;c&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;c=0.4&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:1.4,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;wa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;wb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=2&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;wc&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=c&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;wd&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1.5&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;f(0) = 0&quot;},{&quot;id&quot;:&quot;pc&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(c,f(c))&quot;,&quot;color&quot;:&quot;#c74440&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: זה ש-$f$ מוגדרת ב-$[a,b]$ לא מחבר את $f(a)$ לגבול מ-$(a,b)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: זה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מוגדרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> לא מחבר את <span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\)</span> לגבול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span></p><div class=\"callout-body\"><p>בטענה 1: האם הפונקציה חייבת להיות רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> רק בגלל שהיא מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>?</span></span> מה עם הפונקציה שנותנת <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x-a}\\)</span></span> בפנים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>?</span></p></div></div>"},{"title":"רמז 2: ההבדל בין רציפות ב-$(a,b)$ לרציפות ב-$[a,b]$ בטענה 2","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: ההבדל בין רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> לרציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> בטענה 2</p><div class=\"callout-body\"><p>הנתון בטענה 2 מבטיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה בכל נקודה של הקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span> האם זה מבטיח משהו על הרציפות החד-צדדית בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפריך את טענה 1 בעזרת <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{1}{x-a}\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(a)=f(b)=0\\)</span>:</span></span> היא מוגדרת בכל <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> וחסומה על כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span>,</span> אך אינה חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span> נפריך את טענה 2 בעזרת פונקציה קבועה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b]\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>:</span></span> היא רציפה על כל <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span> אך אינה רציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> ולכן אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: לא נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f:[a,b]\\to\\mathbb R\\)</span> (כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;b\\)</span>)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}\\frac{1}{x-a} &amp; a&lt;x&lt;b \\\\ 0 &amp; x=a\\text{ או }x=b.\\end{cases}\\]</div>\n<p>הפונקציה מוגדרת בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לכל קטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;c\\le x\\le d&lt;b\\)</span>,</span> ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[c,d]\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;f(x)=\\frac{1}{x-a}\\le\\frac{1}{c-a},\\]</div>\n<p>כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span></span> (וגם רציפה בו, משפט 5.35).</p>\n<p><em>למה?</em> העובדה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> קיבלה ערך מסוים <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=a\\)</span></span> אינה מונעת ממנה לנסוק לאינסוף כשמתקרבים אל <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> מבפנים.</p>\n<p>עם זאת, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>:</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span>,</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&lt;b-a\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&lt;\\frac{1}{M+1}\\)</span>;</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(x=a+\\frac1n\\in(a,b)\\)</span> נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=n&gt;M+1&gt;M\\)</span>.</span></p>\n<p><strong>טענה 2: לא נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f:[a,b]\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}1 &amp; x=a \\\\ 0 &amp; a&lt;x\\le b.\\end{cases}\\]</div>\n<p>לכל קטע סגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span>,</span> הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> אינה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> באופן קבוע על <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span> ומכאן שהיא רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span>.</span></span></p>\n<p>ואולם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=a\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=0\\ne 1=f(a)\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה רציפה מימין <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span></span> ולפי הגדרה 5.26 אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: אף טענה אינה נכונה (תשובה <strong>ד</strong>).</p></div></div>","steps":["<p><strong>טענה 1: לא נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f:[a,b]\\to\\mathbb R\\)</span> (כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;b\\)</span>)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}\\frac{1}{x-a} &amp; a&lt;x&lt;b \\\\ 0 &amp; x=a\\text{ או }x=b.\\end{cases}\\]</div>\n<p>הפונקציה מוגדרת בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לכל קטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;c\\le x\\le d&lt;b\\)</span>,</span> ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[c,d]\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;f(x)=\\frac{1}{x-a}\\le\\frac{1}{c-a},\\]</div>\n<p>כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span></span> (וגם רציפה בו, משפט 5.35).</p>\n<p><em>למה?</em> העובדה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> קיבלה ערך מסוים <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=a\\)</span></span> אינה מונעת ממנה לנסוק לאינסוף כשמתקרבים אל <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> מבפנים.</p>\n<p>עם זאת, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>:</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span>,</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&lt;b-a\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&lt;\\frac{1}{M+1}\\)</span>;</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(x=a+\\frac1n\\in(a,b)\\)</span> נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=n&gt;M+1&gt;M\\)</span>.</span></p>","<p><strong>טענה 2: לא נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f:[a,b]\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}1 &amp; x=a \\\\ 0 &amp; a&lt;x\\le b.\\end{cases}\\]</div>\n<p>לכל קטע סגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span>,</span> הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> אינה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> באופן קבוע על <span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span> ומכאן שהיא רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\)</span>.</span></span></p>\n<p>ואולם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=a\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=0\\ne 1=f(a)\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה רציפה מימין <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span></span> ולפי הגדרה 5.26 אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: אף טענה אינה נכונה (תשובה <strong>ד</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להתבלבל בטענה 1 ולחשוב: &quot;הרי נתון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> כלומר גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> אז למה שתקפוץ לאינסוף?&quot; — פונקציה שמוגדרת בקטע סגור לא חייבת להיות רציפה או חסומה בו.</li><li>להתבלבל בטענה 2 ולסמן &quot;נכונה&quot; כי חושבים על המסקנה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> (כמו במועד 81, ששם הוכחנו רציפות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>),</span></span> ולפספס שהפעם הטענה דורשת רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> הסגור!</li></ul></div></div>"}],"similar":"","mc":{"1":false,"2":false}}};
